struct FDORBuildTiming
{
    struct FTotal { int32 Calls=0; double Seconds=0; };
    TMap<FString,FTotal> Totals;
    double Started=FPlatformTime::Seconds();
    bool bEnabled;

    explicit FDORBuildTiming(bool Enabled):bEnabled(Enabled){}
    ~FDORBuildTiming()
    {
        if(!bEnabled)return;
        Totals.KeySort(TLess<FString>());
        for(const auto& Entry:Totals)
            UE_LOG(LogDORGenerateAssets,Display,TEXT("DOR-BUILD-TIME %s calls=%d seconds=%.6f"),
                *Entry.Key,Entry.Value.Calls,Entry.Value.Seconds);
        UE_LOG(LogDORGenerateAssets,Display,TEXT("DOR-BUILD-TIME generationWall=%.6f"),
            FPlatformTime::Seconds()-Started);
    }
    void Record(const FString& Name,double Start)
    {
        auto& Total=Totals.FindOrAdd(Name);
        ++Total.Calls;
        Total.Seconds+=FPlatformTime::Seconds()-Start;
    }
};
FDORBuildTiming* DORActiveBuildTiming=nullptr;

// This translation unit builds the emitted graphs. Instrument its explicit
// compile calls in place, including the shared graph helpers in its .inl files.
struct FDORTimedKismetEditorUtilities : FKismetEditorUtilities
{
    static void CompileBlueprint(UBlueprint* BP,EBlueprintCompileOptions Options=EBlueprintCompileOptions::None,
        FCompilerResultsLog* Results=nullptr)
    {
        const double Start=DORActiveBuildTiming?FPlatformTime::Seconds():0;
        FKismetEditorUtilities::CompileBlueprint(BP,Options,Results);
        if(DORActiveBuildTiming)DORActiveBuildTiming->Record(TEXT("compile ")+GetNameSafe(BP),Start);
    }
};
#define FKismetEditorUtilities FDORTimedKismetEditorUtilities

template<typename Action>
bool DORTimeValidation(const TCHAR* Name,Action Check)
{
    const double Start=DORActiveBuildTiming?FPlatformTime::Seconds():0;
    const bool Passed=Check();
    if(DORActiveBuildTiming)DORActiveBuildTiming->Record(FString(TEXT("validate "))+Name,Start);
    return Passed;
}
