TSet<int32>& DORSupportedPairTestIndices()
{
    static TSet<int32> Indices = { 277, 359, 385, 388, 435, 438, 444 };
    return Indices;
}

bool DORIsSupportedPairTestIndex(const int32 TestIndex)
{
    return DORSupportedPairTestIndices().Contains(TestIndex);
}

FString DORRuntimeRouteIdentity()
{
    TArray<int32> Indices=DORSupportedPairTestIndices().Array();Indices.Sort();
    FString List;
    for(int32 Index:Indices)List+=FString::Printf(TEXT("%d,"),Index);
    FTCHARToUTF8 Bytes(*List);uint8 Hash[20];FSHA1::HashBuffer(Bytes.Get(),Bytes.Length(),Hash);
    return FString::Printf(TEXT("routes=%d|route-fingerprint=%s"),Indices.Num(),*BytesToHex(Hash,20));
}

FString DORHandshakeEnvelopePrefix(const TCHAR* Action)
{
    return *Action?FString::Printf(TEXT("[DOR-HS3]|%s|"), Action):TEXT("[DOR-HS3]|");
}

// Each distributed candidate has a unique frozen version. Catalog/build
// integrity remains local; no redundant manifest/route fingerprint wire gate.
FString DORHandshakeIdentityPrefix(const FString&, const TCHAR* Action)
{
    return FString::Printf(TEXT("%s%s|"), *DORHandshakeEnvelopePrefix(Action), DORResearchBuildTag);
}

