void DeleteGeneratedFile(const FString& LongPackageName);

FString PackageFilename(const FString& LongPackageName)
{
    return FPackageName::LongPackageNameToFilename(
        LongPackageName,
        FPackageName::GetAssetPackageExtension());
}

bool SaveAsset(UPackage* Package, UObject* Asset)
{
    if (!Package || !Asset)
    {
        return false;
    }
    Package->MarkPackageDirty();
    const double Start=DORActiveBuildTiming?FPlatformTime::Seconds():0;
    const bool Saved=UPackage::SavePackage(
        Package,
        Asset,
        EObjectFlags::RF_Public | EObjectFlags::RF_Standalone,
        *PackageFilename(Package->GetName()));
    if(DORActiveBuildTiming)DORActiveBuildTiming->Record(TEXT("save packages"),Start);
    return Saved;
}

bool CreateSecondaryAnnouncementAssets(TArray<UObject*>& OutAssets)
{
    OutAssets.Reset();
    UClass* DialogClass =
        LoadObject<UClass>(nullptr, TEXT("/Script/FSD.DialogDataAsset"));
    if (!DialogClass)
    {
        return false;
    }
    for (const FDORSecondaryAnnouncement& Row : SecondaryAnnouncements())
    {
        const FString AssetName = FString(TEXT("DOR_Secondary_")) + Row.AssetName;
        const FString PackageName =
            FString(RuntimeRoot) / TEXT("Announcements") / AssetName;
        DeleteGeneratedFile(PackageName);
        UPackage* Package = CreatePackage(nullptr, *PackageName);
        UObject* Dialog = NewObject<UObject>(
            Package,
            DialogClass,
            FName(*AssetName),
            EObjectFlags::RF_Public | EObjectFlags::RF_Standalone);
        if (!Dialog)
        {
            return false;
        }
        auto SetBool = [&](const FName Name, bool Value)
        {
            if (FBoolProperty* Property =
                    FindFProperty<FBoolProperty>(DialogClass, Name))
            {
                Property->SetPropertyValue_InContainer(Dialog, Value);
                return true;
            }
            return false;
        };
        auto SetFloat = [&](const FName Name, float Value)
        {
            if (FFloatProperty* Property =
                    FindFProperty<FFloatProperty>(DialogClass, Name))
            {
                Property->SetPropertyValue_InContainer(Dialog, Value);
                return true;
            }
            return false;
        };
        FArrayProperty* EntriesProperty =
            FindFProperty<FArrayProperty>(DialogClass, TEXT("Entries"));
        FStructProperty* EntryStruct = EntriesProperty
            ? CastField<FStructProperty>(EntriesProperty->Inner)
            : nullptr;
        if (!SetBool(TEXT("Enabled"), true) ||
            !SetBool(TEXT("AudioOnly"), false) ||
            !SetBool(TEXT("SelectUsingWeight"), false) ||
            !SetFloat(TEXT("ShoutDelay"), 0.0f) ||
            !SetFloat(TEXT("ShoutCoolDown"), 0.0f) ||
            !SetFloat(TEXT("ShoutChance"), 1.0f) ||
            !EntriesProperty || !EntryStruct)
        {
            return false;
        }
        FScriptArrayHelper Entries(
            EntriesProperty,
            EntriesProperty->ContainerPtrToValuePtr<void>(Dialog));
        Entries.EmptyValues();
        FDialogStruct* Entry =
            reinterpret_cast<FDialogStruct*>(Entries.GetRawPtr(Entries.AddValue()));
        if (!Entry)
        {
            return false;
        }
        Entry->Enabled = true;
        Entry->Text = FText::FromString(Row.TextZh);
        Entry->Audio = TSoftObjectPtr<USoundBase>(
            FSoftObjectPath(
                TEXT("/Game/Audio/Characters/Voices/MissionControl/"
                     "MissionControlSpeakMarch2022/"
                     "MissWaveWarnNewEditions_01_Cue."
                     "MissWaveWarnNewEditions_01_Cue")));
        Entry->Weigth = 1.0f;
        Entry->bIsValidEntry = true;
        FAssetRegistryModule::AssetCreated(Dialog);
        if (!SaveAsset(Package, Dialog))
        {
            return false;
        }
        OutAssets.Add(Dialog);
    }
    return OutAssets.Num() == SecondaryAnnouncements().Num();
}

bool SaveBlueprint(UBlueprint* Blueprint)
{
    if (!Blueprint)
    {
        return false;
    }
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    if (Blueprint->Status == BS_Error)
    {
        UE_LOG(LogDORGenerateAssets, Error, TEXT("Blueprint compile failed: %s"), *Blueprint->GetPathName());
        return false;
    }
    return SaveAsset(Blueprint->GetOutermost(), Blueprint);
}

void DeleteGeneratedFile(const FString& LongPackageName)
{
    const FString Filename = PackageFilename(LongPackageName);
    if (FPaths::FileExists(Filename) && !IFileManager::Get().Delete(*Filename, false, true))
    {
        UE_LOG(LogDORGenerateAssets, Warning, TEXT("Could not remove stale generated asset %s"), *Filename);
    }
}

bool ReadManifestMetadata(
    const FString& Filename,
    FString& OutManifestHash,
    int32& OutPairCount,
    int32& OutOverclockCount)
{
    FString Text;
    if (!FFileHelper::LoadFileToString(Text, *Filename))
    {
        UE_LOG(LogDORGenerateAssets, Error, TEXT("Cannot read runtime manifest: %s"), *Filename);
        return false;
    }
    TSharedPtr<FJsonObject> Root;
    const TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Text);
    if (!FJsonSerializer::Deserialize(Reader, Root) || !Root.IsValid())
    {
        UE_LOG(LogDORGenerateAssets, Error, TEXT("Invalid runtime manifest JSON: %s"), *Filename);
        return false;
    }
    if (Root->GetStringField(TEXT("schema")) != TEXT("dual-overclock-reward.runtime-manifest.v1"))
    {
        UE_LOG(LogDORGenerateAssets, Error, TEXT("Unsupported runtime manifest schema."));
        return false;
    }
    OutManifestHash = Root->GetStringField(TEXT("manifestHash"));
    const TSharedPtr<FJsonObject>* Metadata = nullptr;
    if (!Root->TryGetObjectField(TEXT("metadata"), Metadata) || !Metadata || !Metadata->IsValid())
    {
        UE_LOG(LogDORGenerateAssets, Error, TEXT("Runtime manifest metadata is missing."));
        return false;
    }
    OutPairCount = static_cast<int32>((*Metadata)->GetNumberField(TEXT("supportedPairCount")));
    OutOverclockCount = static_cast<int32>((*Metadata)->GetNumberField(TEXT("overclockCount")));
    if (OutPairCount != 456 || OutOverclockCount != 160)
    {
        UE_LOG(
            LogDORGenerateAssets,
            Error,
            TEXT("Runtime manifest count mismatch: pairs=%d overclocks=%d"),
            OutPairCount,
            OutOverclockCount);
        return false;
    }
    return true;
}

extern bool DORPublicPreparedClosureVerified;

bool ReadManifestPairs(const FString& Filename, TArray<TSharedPtr<FJsonObject>>& OutPairs)
{
    FString Text;
    TSharedPtr<FJsonObject> Root;
    if (!FFileHelper::LoadFileToString(Text, *Filename) ||
        !FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Text), Root) ||
        !Root.IsValid())
    {
        return false;
    }
    if (Root->HasField(TEXT("provenance")) && !DORPublicPreparedClosureVerified) return false;
    const TArray<TSharedPtr<FJsonValue>>* Values = nullptr;
    if (!Root->TryGetArrayField(TEXT("pairs"), Values) || !Values)
    {
        return false;
    }
    OutPairs.Reset();
    for (const TSharedPtr<FJsonValue>& Value : *Values)
    {
        const TSharedPtr<FJsonObject> Pair = Value->AsObject();
        if (!Pair.IsValid())
        {
            return false;
        }
        OutPairs.Add(Pair);
    }
    return OutPairs.Num() == 456;
}

bool ReadManifestOverclocks(
    const FString& Filename,
    TArray<TSharedPtr<FJsonObject>>& OutOverclocks)
{
    FString Text;
    TSharedPtr<FJsonObject> Root;
    if (!FFileHelper::LoadFileToString(Text, *Filename) ||
        !FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Text), Root) ||
        !Root.IsValid())
    {
        return false;
    }
    const TArray<TSharedPtr<FJsonValue>>* Values = nullptr;
    if (!Root->TryGetArrayField(TEXT("overclocks"), Values) || !Values)
    {
        return false;
    }
    OutOverclocks.Reset();
    for (const TSharedPtr<FJsonValue>& Value : *Values)
    {
        const TSharedPtr<FJsonObject> Overclock = Value->AsObject();
        if (!Overclock.IsValid())
        {
            return false;
        }
        OutOverclocks.Add(Overclock);
    }
    return OutOverclocks.Num() == 160;
}

