UItemID* CreatePair388MirrorItemId(UClass* MirrorWeaponClass)
{
    if (!MirrorWeaponClass)
    {
        UE_LOG(
            LogDORGenerateAssets,
            Error,
            TEXT("DOR-E-PAIR388-MIRROR-ID-001: mirror class is unavailable."));
        return nullptr;
    }

    const FString PackageName =
        FString(RuntimeRoot) /
        TEXT("Weapons/PlasmaCarbine/ID_DOR_PlasmaCarbine");
    const FName AssetName(TEXT("ID_DOR_PlasmaCarbine"));
    DeleteGeneratedFile(PackageName);
    UPackage* Package = CreatePackage(nullptr, *PackageName);
    UItemID* MirrorItemId = NewObject<UItemID>(
        Package,
        UItemID::StaticClass(),
        AssetName,
        EObjectFlags::RF_Public | EObjectFlags::RF_Standalone);
    if (!MirrorItemId)
    {
        return nullptr;
    }
    FStructProperty* SaveIdProperty = FindFProperty<FStructProperty>(
        UItemID::StaticClass(),
        TEXT("SavegameID"));
    FSoftObjectProperty* ItemProperty = FindFProperty<FSoftObjectProperty>(
        UItemID::StaticClass(),
        TEXT("Item"));
    if (!SaveIdProperty || !ItemProperty)
    {
        UE_LOG(
            LogDORGenerateAssets,
            Error,
            TEXT("DOR-E-PAIR388-MIRROR-ID-002: required ItemID fields are unavailable."));
        return nullptr;
    }

    *SaveIdProperty->ContainerPtrToValuePtr<FGuid>(MirrorItemId) =
        FGuid(0xD0388A25, 0x7A114B9D, 0x9338A2ED, 0xC4FA1D61);
    ItemProperty->SetPropertyValue_InContainer(
        MirrorItemId,
        FSoftObjectPtr(FSoftObjectPath(MirrorWeaponClass)));
    FAssetRegistryModule::AssetCreated(MirrorItemId);
    return MirrorItemId;
}

template <typename TNode>
TNode* AddNode(UEdGraph* Graph, int32 X, int32 Y)
{
    TNode* Node = NewObject<TNode>(Graph);
    Graph->AddNode(Node, true, false);
    Node->CreateNewGuid();
    Node->NodePosX = X;
    Node->NodePosY = Y;
    return Node;
}

UEdGraph* FindStandardMacroGraph(const FName MacroName)
{
    UBlueprint* StandardMacros = LoadObject<UBlueprint>(
        nullptr,
        TEXT("/Engine/EditorBlueprintResources/StandardMacros.StandardMacros"));
    if (!StandardMacros)
    {
        UE_LOG(LogDORGenerateAssets, Error, TEXT("Could not load StandardMacros."));
        return nullptr;
    }
    for (UEdGraph* Graph : StandardMacros->MacroGraphs)
    {
        if (Graph && Graph->GetFName() == MacroName)
        {
            return Graph;
        }
    }
    UE_LOG(
        LogDORGenerateAssets,
        Error,
        TEXT("Could not find StandardMacros graph %s."),
        *MacroName.ToString());
    return nullptr;
}

UK2Node_CallFunction* AddCall(UEdGraph* Graph, UClass* Class, const FName Function, int32 X, int32 Y)
{
    UK2Node_CallFunction* Node = AddNode<UK2Node_CallFunction>(Graph, X, Y);
    Node->FunctionReference.SetExternalMember(Function, Class);
    Node->AllocateDefaultPins();
    return Node;
}

UK2Node_CallArrayFunction* AddArrayCall(UEdGraph* Graph, const FName Function, int32 X, int32 Y)
{
    UK2Node_CallArrayFunction* Node = AddNode<UK2Node_CallArrayFunction>(Graph, X, Y);
    Node->FunctionReference.SetExternalMember(Function, UKismetArrayLibrary::StaticClass());
    Node->AllocateDefaultPins();
    return Node;
}

UEdGraphPin* FindPin(UEdGraphNode* Node, const FName Name)
{
    return Node ? Node->FindPin(Name) : nullptr;
}

UEdGraphPin* FindStructInputPin(UEdGraphNode* Node)
{
    if (!Node)
    {
        return nullptr;
    }
    for (UEdGraphPin* Pin : Node->Pins)
    {
        if (Pin && Pin->Direction == EGPD_Input &&
            Pin->PinType.PinCategory == UEdGraphSchema_K2::PC_Struct)
        {
            return Pin;
        }
    }
    return nullptr;
}

UEdGraphPin* FindStructOutputPin(UEdGraphNode* Node)
{
    if (!Node)
    {
        return nullptr;
    }
    for (UEdGraphPin* Pin : Node->Pins)
    {
        if (Pin && Pin->Direction == EGPD_Output &&
            Pin->PinType.PinCategory == UEdGraphSchema_K2::PC_Struct)
        {
            return Pin;
        }
    }
    return nullptr;
}

