UK2Node_FunctionEntry* FindFunctionEntry(UEdGraph* Graph)
{
    if (!Graph)
    {
        return nullptr;
    }
    for (UEdGraphNode* Node : Graph->Nodes)
    {
        if (UK2Node_FunctionEntry* Entry = Cast<UK2Node_FunctionEntry>(Node))
        {
            return Entry;
        }
    }
    return nullptr;
}

UEdGraph* FindFunctionGraph(UBlueprint* Blueprint, const FName Name)
{
    if (!Blueprint)
    {
        return nullptr;
    }
    for (UEdGraph* Graph : Blueprint->FunctionGraphs)
    {
        if (Graph && Graph->GetFName() == Name)
        {
            return Graph;
        }
    }
    return nullptr;
}

UK2Node_FunctionEntry* ClearFunctionBody(UEdGraph* Graph)
{
    UK2Node_FunctionEntry* Entry = FindFunctionEntry(Graph);
    if (!Graph || !Entry)
    {
        return nullptr;
    }
    const TArray<UEdGraphNode*> ExistingNodes = Graph->Nodes;
    for (UEdGraphNode* Node : ExistingNodes)
    {
        if (Node && Node != Entry)
        {
            Node->BreakAllNodeLinks();
            Node->DestroyNode();
        }
    }
    Entry->BreakAllNodeLinks();
    return Entry;
}

UEdGraphPin* AddFunctionInput(UEdGraph* Graph, const FName Name, const FEdGraphPinType& Type)
{
    UK2Node_FunctionEntry* Entry = FindFunctionEntry(Graph);
    if (!Entry)
    {
        return nullptr;
    }
    UEdGraphPin* Pin = Entry->CreateUserDefinedPin(Name, Type, EGPD_Output);
    ForcePinType(Pin, Type);
    return Pin;
}

bool Connect(UEdGraphPin* From, UEdGraphPin* To)
{
    if (!From || !To)
    {
        UE_LOG(
            LogDORGenerateAssets,
            Error,
            TEXT("DOR-E-GRAPH-CONNECT: null pin from=%s node=%s graph=%s to=%s node=%s graph=%s"),
            From ? *From->GetName() : TEXT("<null>"),
            From && From->GetOwningNode() ? *From->GetOwningNode()->GetName() : TEXT("<null>"),
            From && From->GetOwningNode() && From->GetOwningNode()->GetGraph()
                ? *From->GetOwningNode()->GetGraph()->GetName()
                : TEXT("<null>"),
            To ? *To->GetName() : TEXT("<null>"),
            To && To->GetOwningNode() ? *To->GetOwningNode()->GetName() : TEXT("<null>"),
            To && To->GetOwningNode() && To->GetOwningNode()->GetGraph()
                ? *To->GetOwningNode()->GetGraph()->GetName()
                : TEXT("<null>"));
        return false;
    }
    From->MakeLinkTo(To);
    return true;
}

UEdGraphPin* SelfPin(UEdGraph* Graph, int32 X, int32 Y)
{
    UK2Node_Self* Node = AddNode<UK2Node_Self>(Graph, X, Y);
    Node->AllocateDefaultPins();
    return Node->FindPin(UEdGraphSchema_K2::PN_Self);
}

UK2Node_CallFunction* AddDORLog(UEdGraph* Graph, const FString& Message, int32 X, int32 Y)
{
    UK2Node_CallFunction* Node = AddCall(
        Graph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, PrintString),
        X,
        Y);
    FindPin(Node, TEXT("InString"))->DefaultValue = Message;
    FindPin(Node, TEXT("bPrintToScreen"))->DefaultValue = TEXT("false");
    FindPin(Node, TEXT("bPrintToLog"))->DefaultValue = TEXT("true");
    FindPin(Node, TEXT("Duration"))->DefaultValue = TEXT("0.0");
    Connect(SelfPin(Graph, X - 160, Y + 180), FindPin(Node, TEXT("WorldContextObject")));
    return Node;
}

bool AddVariable(UBlueprint* Blueprint, const FName Name, const FName Category, bool bArray = false)
{
    if (FBlueprintEditorUtils::FindNewVariableIndex(Blueprint, Name) != INDEX_NONE)
    {
        return true;
    }
    FEdGraphPinType Type;
    Type.PinCategory = Category;
    Type.ContainerType = bArray ? EPinContainerType::Array : EPinContainerType::None;
    return FBlueprintEditorUtils::AddMemberVariable(Blueprint, Name, Type);
}

bool AddTypedVariable(UBlueprint* Blueprint, const FName Name, const FEdGraphPinType& Type)
{
    if (FBlueprintEditorUtils::FindNewVariableIndex(Blueprint, Name) != INDEX_NONE)
    {
        return true;
    }
    return FBlueprintEditorUtils::AddMemberVariable(Blueprint, Name, Type);
}

bool AddSavedTypedVariable(
    UBlueprint* Blueprint,
    const FName Name,
    const FEdGraphPinType& Type)
{
    if (!AddTypedVariable(Blueprint, Name, Type))
    {
        return false;
    }
    const int32 VariableIndex =
        FBlueprintEditorUtils::FindNewVariableIndex(Blueprint, Name);
    if (VariableIndex == INDEX_NONE ||
        !Blueprint->NewVariables.IsValidIndex(VariableIndex))
    {
        return false;
    }
    Blueprint->NewVariables[VariableIndex].PropertyFlags |= CPF_SaveGame;
    return true;
}

