bool ValidateRefreshLoadoutBindings(UBlueprint* Blueprint)
{
    if (!Blueprint)
    {
        return false;
    }

    bool bOk = true;
    auto ValidateGraph = [&bOk](UEdGraph* Graph)
    {
        if (!Graph)
        {
            return;
        }
        for (UEdGraphNode* Node : Graph->Nodes)
        {
            UK2Node_CallFunction* Call = Cast<UK2Node_CallFunction>(Node);
            if (!Call ||
                Call->FunctionReference.GetMemberName() != TEXT("RefreshLoadoutFromSave"))
            {
                continue;
            }
            UEdGraphPin* Self = FindPin(Call, UEdGraphSchema_K2::PN_Self);
            UEdGraphPin* CharacterId = FindPin(Call, TEXT("characterID"));
            if (!Self || Self->LinkedTo.Num() == 0 ||
                !CharacterId || CharacterId->LinkedTo.Num() == 0)
            {
                UE_LOG(
                    LogDORGenerateAssets,
                    Error,
                    TEXT("DOR-E-ALPHA37-REFRESH-BINDING: graph=%s node=%s self=%s characterID=%s"),
                    *Graph->GetName(),
                    *Call->GetName(),
                    Self && Self->LinkedTo.Num() > 0 ? TEXT("linked") : TEXT("missing"),
                    CharacterId && CharacterId->LinkedTo.Num() > 0
                        ? TEXT("linked")
                        : TEXT("missing"));
                bOk = false;
            }
        }
    };

    for (UEdGraph* Graph : Blueprint->FunctionGraphs)
    {
        ValidateGraph(Graph);
    }
    for (UEdGraph* Graph : Blueprint->UbergraphPages)
    {
        ValidateGraph(Graph);
    }
    return bOk;
}

bool BuildPair388CandidateWeaponInjection(UBlueprint* Blueprint)
{
    if (!Blueprint || !Blueprint->ParentClass)
    {
        return false;
    }

    const FName ScratchName(TEXT("DORUpgradeScratch"));
    const FName ExecutedName(TEXT("DORConstructionInjectionExecuted"));
    const FName InputCountName(TEXT("DORConstructionInputCount"));
    const FName FinalCountName(TEXT("DORConstructionFinalCount"));
    bool bOk = true;
    bOk &= AddTypedVariable(
        Blueprint, ScratchName, MakeItemUpgradePinType(true));
    bOk &= AddVariable(
        Blueprint, ExecutedName, UEdGraphSchema_K2::PC_Boolean);
    bOk &= AddVariable(Blueprint, InputCountName, UEdGraphSchema_K2::PC_Int);
    bOk &= AddVariable(Blueprint, FinalCountName, UEdGraphSchema_K2::PC_Int);
    if (!bOk)
    {
        return false;
    }

    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    UEdGraph* EventGraph = FBlueprintEditorUtils::FindEventGraph(Blueprint);
    UClass* UpgradableInterfaceClass =
        LoadObject<UClass>(nullptr, TEXT("/Script/FSD.Upgradable"));
    UFunction* ParentUpgraded =
        Blueprint->ParentClass->FindFunctionByName(TEXT("Upgraded"));
    if (!EventGraph || !UpgradableInterfaceClass || !ParentUpgraded)
    {
        UE_LOG(
            LogDORGenerateAssets,
            Error,
            TEXT("DOR-E-ALPHA32-UPGRADED-001: parent Upgraded event is unavailable."));
        return false;
    }

    UK2Node_Event* UpgradedEvent =
        AddNode<UK2Node_Event>(EventGraph, 0, 0);
    UpgradedEvent->EventReference.SetExternalMember(
        TEXT("Upgraded"), UpgradableInterfaceClass);
    UpgradedEvent->bOverrideFunction = true;
    UpgradedEvent->AllocateDefaultPins();

    UEdGraphPin* EventExec = FindPin(UpgradedEvent, UEdGraphSchema_K2::PN_Then);
    UEdGraphPin* EventUpgrades = FindPin(UpgradedEvent, TEXT("Upgrades"));
    if (!EventExec || !EventUpgrades)
    {
        UE_LOG(
            LogDORGenerateAssets,
            Error,
            TEXT("DOR-E-ALPHA32-UPGRADED-002: Upgraded event pins are unavailable."));
        return false;
    }
    ForcePinType(EventUpgrades, MakeItemUpgradePinType(true));

    UK2Node_CallFunction* MakeCandidatePath = AddCall(
        EventGraph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, MakeSoftObjectPath),
        260,
        -220);
    FindPin(MakeCandidatePath, TEXT("PathString"))->DefaultValue =
        TEXT("/Game/WeaponsNTools/PlasmaCarbine/Overclocks/"
             "OC_PlasmaCarbine_ElementalWeakness."
             "OC_PlasmaCarbine_ElementalWeakness");
    UK2Node_CallFunction* CandidateSoftReference = AddCall(
        EventGraph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(
            UKismetSystemLibrary, Conv_SoftObjPathToSoftObjRef),
        520,
        -220);
    UK2Node_CallFunction* LoadCandidate = AddCall(
        EventGraph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, LoadAsset_Blocking),
        780,
        -220);
    UK2Node_DynamicCast* CastCandidate =
        AddNode<UK2Node_DynamicCast>(EventGraph, 1040, -220);
    CastCandidate->TargetType = UItemUpgrade::StaticClass();
    CastCandidate->SetPurity(false);
    CastCandidate->AllocateDefaultPins();
    ForcePinType(
        CastCandidate->GetCastSourcePin(), MakeObjectPinType(UObject::StaticClass()));

    UK2Node_CallArrayFunction* InputLength = AddArrayCall(
        EventGraph,
        GET_FUNCTION_NAME_CHECKED(UKismetArrayLibrary, Array_Length),
        260,
        180);
    ForcePinType(
        FindPin(InputLength, TEXT("TargetArray")), MakeItemUpgradePinType(true));
    UK2Node_VariableSet* SetInputCount =
        AddVariableSet(EventGraph, InputCountName, 260, 0);
    UK2Node_VariableSet* SetScratch =
        AddVariableSet(EventGraph, ScratchName, 520, 0);
    ForcePinType(
        FindPin(SetScratch, ScratchName), MakeItemUpgradePinType(true));

    UK2Node_VariableGet* ScratchForAdd =
        AddVariableGet(EventGraph, ScratchName, 780, 180);
    ForcePinType(ScratchForAdd->GetValuePin(), MakeItemUpgradePinType(true));
    UK2Node_CallArrayFunction* AddCandidate = AddArrayCall(
        EventGraph,
        GET_FUNCTION_NAME_CHECKED(UKismetArrayLibrary, Array_Add),
        780,
        0);
    ForcePinType(
        FindPin(AddCandidate, TEXT("TargetArray")), MakeItemUpgradePinType(true));
    ForcePinType(
        FindPin(AddCandidate, TEXT("NewItem")), MakeItemUpgradePinType(false));

    UK2Node_VariableGet* ScratchForLength =
        AddVariableGet(EventGraph, ScratchName, 1040, 220);
    ForcePinType(
        ScratchForLength->GetValuePin(), MakeItemUpgradePinType(true));
    UK2Node_CallArrayFunction* FinalLength = AddArrayCall(
        EventGraph,
        GET_FUNCTION_NAME_CHECKED(UKismetArrayLibrary, Array_Length),
        1040,
        80);
    ForcePinType(
        FindPin(FinalLength, TEXT("TargetArray")), MakeItemUpgradePinType(true));
    UK2Node_VariableSet* SetFinalCount =
        AddVariableSet(EventGraph, FinalCountName, 1300, 0);
    UK2Node_VariableSet* SetExecuted =
        AddVariableSet(EventGraph, ExecutedName, 1560, 0);
    FindPin(SetExecuted, ExecutedName)->DefaultValue = TEXT("true");

    UK2Node_CallParentFunction* CallParent =
        AddNode<UK2Node_CallParentFunction>(EventGraph, 1820, 0);
    CallParent->SetFromFunction(ParentUpgraded);
    CallParent->AllocateDefaultPins();
    UEdGraphPin* ParentUpgrades = FindPin(CallParent, TEXT("Upgrades"));
    if (!ParentUpgrades)
    {
        UE_LOG(
            LogDORGenerateAssets,
            Error,
            TEXT("DOR-E-ALPHA32-UPGRADED-003: parent Upgraded input is unavailable."));
        return false;
    }
    ForcePinType(ParentUpgrades, MakeItemUpgradePinType(true));
    UK2Node_VariableGet* ScratchForParent =
        AddVariableGet(EventGraph, ScratchName, 1560, 260);
    ForcePinType(
        ScratchForParent->GetValuePin(), MakeItemUpgradePinType(true));
    UK2Node_CallFunction* ConstructionLog = AddDORLog(
        EventGraph,
        TEXT("[DOR]|build=0.8.0-alpha32|event=CANDIDATE_CONSTRUCTION_INJECT|result=ok|test=388|candidate=OC_PlasmaCarbine_ElementalWeakness|persistent-save-write=false"),
        2080,
        0);

    UK2Node_CallParentFunction* FallbackParent =
        AddNode<UK2Node_CallParentFunction>(EventGraph, 1300, -360);
    FallbackParent->SetFromFunction(ParentUpgraded);
    FallbackParent->AllocateDefaultPins();
    UEdGraphPin* FallbackUpgrades = FindPin(FallbackParent, TEXT("Upgrades"));
    ForcePinType(FallbackUpgrades, MakeItemUpgradePinType(true));
    UK2Node_CallFunction* FallbackLog = AddDORLog(
        EventGraph,
        TEXT("[DOR]|build=0.8.0-alpha32|event=CANDIDATE_CONSTRUCTION_INJECT|result=fallback|code=DOR-E-ALPHA32-CANDIDATE-LOAD|persistent-save-write=false"),
        1560,
        -360);

    bOk &= Connect(
        MakeCandidatePath->GetReturnValuePin(),
        FindPin(CandidateSoftReference, TEXT("SoftObjectPath")));
    bOk &= Connect(
        CandidateSoftReference->GetReturnValuePin(),
        FindPin(LoadCandidate, TEXT("Asset")));
    bOk &= Connect(EventExec, LoadCandidate->GetExecPin());
    bOk &= Connect(
        LoadCandidate->GetReturnValuePin(), CastCandidate->GetCastSourcePin());
    bOk &= Connect(LoadCandidate->GetThenPin(), CastCandidate->GetExecPin());
    bOk &= Connect(EventUpgrades, FindPin(InputLength, TEXT("TargetArray")));
    bOk &= Connect(
        InputLength->GetReturnValuePin(), FindPin(SetInputCount, InputCountName));
    bOk &= Connect(
        CastCandidate->GetValidCastPin(), SetInputCount->GetExecPin());
    bOk &= Connect(
        FindPin(SetInputCount, UEdGraphSchema_K2::PN_Then),
        SetScratch->GetExecPin());
    bOk &= Connect(EventUpgrades, FindPin(SetScratch, ScratchName));
    bOk &= Connect(
        FindPin(SetScratch, UEdGraphSchema_K2::PN_Then),
        AddCandidate->GetExecPin());
    bOk &= Connect(
        ScratchForAdd->GetValuePin(), FindPin(AddCandidate, TEXT("TargetArray")));
    bOk &= Connect(
        CastCandidate->GetCastResultPin(), FindPin(AddCandidate, TEXT("NewItem")));
    bOk &= Connect(
        ScratchForLength->GetValuePin(), FindPin(FinalLength, TEXT("TargetArray")));
    bOk &= Connect(AddCandidate->GetThenPin(), SetFinalCount->GetExecPin());
    bOk &= Connect(
        FinalLength->GetReturnValuePin(), FindPin(SetFinalCount, FinalCountName));
    bOk &= Connect(
        FindPin(SetFinalCount, UEdGraphSchema_K2::PN_Then),
        SetExecuted->GetExecPin());
    bOk &= Connect(
        FindPin(SetExecuted, UEdGraphSchema_K2::PN_Then),
        CallParent->GetExecPin());
    bOk &= Connect(
        ScratchForParent->GetValuePin(), ParentUpgrades);
    bOk &= Connect(CallParent->GetThenPin(), ConstructionLog->GetExecPin());
    bOk &= Connect(
        CastCandidate->GetInvalidCastPin(), FallbackParent->GetExecPin());
    bOk &= Connect(EventUpgrades, FallbackUpgrades);
    bOk &= Connect(FallbackParent->GetThenPin(), FallbackLog->GetExecPin());
    if (!bOk)
    {
        return false;
    }

    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    if (Blueprint->Status == BS_Error || !Blueprint->GeneratedClass)
    {
        UE_LOG(
            LogDORGenerateAssets,
            Error,
            TEXT("DOR-E-ALPHA32-UPGRADED-004: candidate weapon failed to compile."));
        return false;
    }

    return true;
}

UBlueprint* CreateObjectBlueprint(
    const FString& PackageName,
    const FString& AssetName,
    UClass* ParentClass)
{
    DeleteGeneratedFile(PackageName);
    UPackage* Package = CreatePackage(nullptr, *PackageName);
    UBlueprint* Blueprint = FKismetEditorUtilities::CreateBlueprint(
        ParentClass,
        Package,
        FName(*AssetName),
        BPTYPE_Normal,
        UBlueprint::StaticClass(),
        UBlueprintGeneratedClass::StaticClass(),
        FName(TEXT("DORGenerateAssets")));
    if (!Blueprint)
    {
        return nullptr;
    }
    FAssetRegistryModule::AssetCreated(Blueprint);
    return Blueprint;
}

#include "DORSaveSafety.inl"

struct FDORStablePlayerKeyPins
{
    UK2Node_CallFunction* Call = nullptr;
    UEdGraphPin* Key = nullptr;
    UEdGraphPin* Ready = nullptr;
};

FDORStablePlayerKeyPins AddDORNetworkIdEncoding(
    UEdGraph* Graph,
    UEdGraphPin* PlayerState,
    const int32 X,
    const int32 Y)
{
    UK2Node_VariableGet* GetUniqueId = AddExternalVariableGet(
        Graph,
        TEXT("UniqueId"),
        APlayerState::StaticClass(),
        X,
        Y);
    UK2Node_MakeStruct* MakeMessage = AddNode<UK2Node_MakeStruct>(
        Graph,
        X + 220,
        Y);
    MakeMessage->StructType = FFSDChatMessage::StaticStruct();
    MakeMessage->bMadeAfterOverridePinRemoval = true;
    MakeMessage->AllocateDefaultPins();
    UEdGraphPin* MessageOutput = nullptr;
    for (UEdGraphPin* Pin : MakeMessage->Pins)
    {
        if (Pin && Pin->Direction == EGPD_Output &&
            Pin->PinType.PinCategory == UEdGraphSchema_K2::PC_Struct)
        {
            MessageOutput = Pin;
            break;
        }
    }
    UClass* MessagingClass = LoadObject<UClass>(
        nullptr, TEXT("/Script/FSD.MessagingSubSystem"));
    UK2Node_CallFunction* EncodeNetworkId = AddCall(
        Graph,
        MessagingClass,
        TEXT("MessageSenderIdAsString"),
        X + 440,
        Y);

    Connect(PlayerState, FindPin(GetUniqueId, UEdGraphSchema_K2::PN_Self));
    Connect(GetUniqueId->GetValuePin(), FindPin(MakeMessage, TEXT("SenderNetID")));
    Connect(MessageOutput, FindPin(EncodeNetworkId, TEXT("Msg")));
    return { EncodeNetworkId, EncodeNetworkId->GetReturnValuePin(), nullptr };
}

UK2Node_FunctionResult* AddDORStableIdentityResult(
    FDORSafeGraph& F,
    UEdGraphPin* Key,
    const bool bReady)
{
    auto* Result = AddNode<UK2Node_FunctionResult>(F.G, ++F.Serial * 160, 0);
    Result->FunctionReference = F.Entry->FunctionReference;
    Result->AllocateDefaultPins();
    auto EnsureOutput = [&](const FName Name, const FEdGraphPinType& Type)
    {
        if (UEdGraphPin* Existing = Result->FindPin(Name)) return Existing;
        UEdGraphPin* Pin = Result->CreateUserDefinedPin(Name, Type, EGPD_Input);
        const FName GeneratedName = Pin->PinName;
        Pin->PinName = Name;
        for (auto& Info : Result->UserDefinedPins)
            if (Info->PinName == GeneratedName) Info->PinName = Name;
        ForcePinType(Pin, Type);
        return Pin;
    };
    UEdGraphPin* KeyOutput = EnsureOutput(TEXT("Key"), MakeStringPinType());
    UEdGraphPin* ReadyOutput = EnsureOutput(TEXT("Ready"), MakeBoolPinType());
    if (Key) Connect(Key, KeyOutput); else KeyOutput->DefaultValue = TEXT("");
    ReadyOutput->DefaultValue = bReady ? TEXT("true") : TEXT("false");
    Connect(F.Tail, Result->FindPin(UEdGraphSchema_K2::PN_Execute));
    F.Tail = nullptr;
    return Result;
}

bool BuildDORStableIdentityResolver(UBlueprint* Blueprint)
{
    if (!Blueprint || !AddTypedVariable(
            Blueprint, TEXT("IdentityLastFailureStage"), MakeStringPinType()))
    {
        return false;
    }
    FDORSafeGraph F(Blueprint, TEXT("DOR_ResolveStablePlayerKey"));
    UEdGraphPin* Player = F.Input(
        TEXT("Player"), MakeObjectPinType(APlayerCharacter::StaticClass()));
    auto FinishFailure = [&](const FString& Stage)
    {
        auto* SameStage = F.Equal(
            F.Get(TEXT("IdentityLastFailureStage")),
            DORSafeString(F, Stage),
            TEXT("EqualEqual_StrStr"),
            UKismetStringLibrary::StaticClass());
        auto* Changed = F.Branch(F.Not(SameStage));
        UEdGraphPin* ChangedTail = F.Tail;
        F.Set(TEXT("IdentityLastFailureStage"), DORSafeString(F, Stage));
        auto* Print = F.Call(UKismetSystemLibrary::StaticClass(), TEXT("PrintString"));
        FindPin(Print, TEXT("InString"))->DefaultValue = FString::Printf(
            TEXT("[DOR]|event=IDENTITY_RESOLVE|result=not_ready|stage=%s"), *Stage);
        FindPin(Print, TEXT("bPrintToScreen"))->DefaultValue = TEXT("false");
        FindPin(Print, TEXT("bPrintToLog"))->DefaultValue = TEXT("true");
        AddDORStableIdentityResult(F, nullptr, false);
        F.Tail = Changed->GetElsePin();
        AddDORStableIdentityResult(F, nullptr, false);
        F.Tail = ChangedTail;
    };

    auto* PlayerValid = F.Branch(F.IsValid(Player));
    UEdGraphPin* ValidPlayerTail = F.Tail;
    F.Tail = PlayerValid->GetElsePin();
    FinishFailure(TEXT("missing-player"));
    F.Tail = ValidPlayerTail;

    auto* GetPlayerState = F.Call(
        APlayerCharacter::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(APlayerCharacter, GetPlayerState));
    Connect(Player, FindPin(GetPlayerState, UEdGraphSchema_K2::PN_Self));
    UEdGraphPin* PlayerState = F.Cache(
        TEXT("PlayerState"), GetPlayerState->GetReturnValuePin());
    auto* PlayerStateValid = F.Branch(F.IsValid(PlayerState));
    UEdGraphPin* ValidPlayerStateTail = F.Tail;
    F.Tail = PlayerStateValid->GetElsePin();
    FinishFailure(TEXT("missing-player-state"));
    F.Tail = ValidPlayerStateTail;

    FDORStablePlayerKeyPins Encoding = AddDORNetworkIdEncoding(
        F.G, PlayerState, ++F.Serial * 160, 0);
    UEdGraphPin* RawNetworkId = F.Cache(TEXT("RawNetworkId"), Encoding.Key);
    auto* Empty = F.Equal(
        RawNetworkId,
        DORSafeString(F, TEXT("")),
        TEXT("EqualEqual_StrStr"),
        UKismetStringLibrary::StaticClass());
    auto* NonEmpty = F.Branch(F.Not(Empty));
    UEdGraphPin* NonEmptyTail = F.Tail;
    F.Tail = NonEmpty->GetElsePin();
    FinishFailure(TEXT("invalid-encoding"));
    F.Tail = NonEmptyTail;

    auto* Invalid = F.Equal(
        RawNetworkId,
        DORSafeString(F, TEXT("INVALID")),
        TEXT("EqualEqual_StrStr"),
        UKismetStringLibrary::StaticClass());
    auto* ValidEncoding = F.Branch(F.Not(Invalid));
    UEdGraphPin* ValidEncodingTail = F.Tail;
    F.Tail = ValidEncoding->GetElsePin();
    FinishFailure(TEXT("invalid-encoding"));
    F.Tail = ValidEncodingTail;

    F.Set(TEXT("IdentityLastFailureStage"), DORSafeString(F, TEXT("")));
    UEdGraphPin* Key = DORSafeConcat(F, TEXT("net-v1:"), RawNetworkId);
    AddDORStableIdentityResult(F, Key, true);
    F.Compile();
    return Blueprint->Status != BS_Error;
}

FDORStablePlayerKeyPins AddDORStableIdentityCall(
    UEdGraph* Graph,
    UEdGraphPin* Player,
    const int32 X,
    const int32 Y)
{
    auto* Resolve = AddSelfCall(Graph, TEXT("DOR_ResolveStablePlayerKey"), X, Y);
    Connect(Player, FindPin(Resolve, TEXT("Player")));
    return { Resolve, FindPin(Resolve, TEXT("Key")), FindPin(Resolve, TEXT("Ready")) };
}

UBlueprint* CreatePresetRecoveryBlueprint()
{
    UBlueprint* Blueprint = CreateObjectBlueprint(
        FString(RuntimeRoot) / TEXT("Blueprints/SG_DOR_PresetRecovery"),
        TEXT("SG_DOR_PresetRecovery"),
        USaveGame::StaticClass());
    if (!Blueprint)
    {
        return nullptr;
    }

    bool bOk = true;
    bOk &= AddSavedTypedVariable(
        Blueprint, TEXT("Pending"), MakeBoolPinType(false));
    bOk &= AddSavedTypedVariable(
        Blueprint,
        TEXT("CharacterSavesSnapshot"),
        MakeStructPinType(FCharacterSave::StaticStruct(), true));
    bOk &= AddSavedTypedVariable(
        Blueprint,
        TEXT("UpgradeLoadoutsSnapshot"),
        MakeStructPinType(FUpgradeLoadout::StaticStruct(), true));
    bOk &= AddSavedTypedVariable(
        Blueprint, TEXT("BuildTag"), MakeStringPinType(false));
    bOk &= AddSavedTypedVariable(
        Blueprint, TEXT("Stage"), MakeIntPinType(false));
    bOk &= AddSavedTypedVariable(
        Blueprint, TEXT("StageName"), MakeStringPinType(false));
    if (!bOk)
    {
        return nullptr;
    }

    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    return Blueprint->Status == BS_Error ? nullptr : Blueprint;
}

UBlueprint* CreateDiagnosticSnapshotBlueprint()
{
    UBlueprint* Blueprint = CreateObjectBlueprint(
        FString(RuntimeRoot) / TEXT("Blueprints/SG_DOR_DiagnosticsV1"),
        TEXT("SG_DOR_DiagnosticsV1"),
        USaveGame::StaticClass());
    if (!Blueprint)
    {
        return nullptr;
    }
    bool bOk = true;
    bOk &= AddSavedTypedVariable(Blueprint, TEXT("Schema"), MakeStringPinType(false));
    bOk &= AddSavedTypedVariable(Blueprint, TEXT("Sequence"), MakeIntPinType(false));
    bOk &= AddSavedTypedVariable(Blueprint, TEXT("Snapshot"), MakeStringPinType(false));
    if (!bOk)
    {
        return nullptr;
    }
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    return Blueprint->Status == BS_Error ? nullptr : Blueprint;
}

bool BuildPresetRecoveryGuard(UBlueprint* Blueprint, UClass* RecoveryClass)
{
    if (!Blueprint || !RecoveryClass ||
        !RecoveryClass->IsChildOf(USaveGame::StaticClass()))
    {
        return false;
    }

    const FEdGraphPinType CharacterSaveArrayType =
        MakeStructPinType(FCharacterSave::StaticStruct(), true);
    const FEdGraphPinType UpgradeLoadoutArrayType =
        MakeStructPinType(FUpgradeLoadout::StaticStruct(), true);
    UEdGraph* Graph = FBlueprintEditorUtils::FindEventGraph(Blueprint);
    if (!Graph)
    {
        return false;
    }
    Graph->Nodes.Empty();

    UK2Node_Event* BeginPlay = AddNode<UK2Node_Event>(Graph, 0, 0);
    BeginPlay->EventReference.SetExternalMember(
        TEXT("ReceiveBeginPlay"), AActor::StaticClass());
    BeginPlay->bOverrideFunction = true;
    BeginPlay->AllocateDefaultPins();

    UK2Node_CallFunction* Delay = AddCall(
        Graph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, Delay),
        260,
        0);
    FindPin(Delay, TEXT("Duration"))->DefaultValue = TEXT("0.5");
    UK2Node_CallFunction* DoesRecoveryExist = AddCall(
        Graph,
        UGameplayStatics::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UGameplayStatics, DoesSaveGameExist),
        520,
        160);
    FindPin(DoesRecoveryExist, TEXT("SlotName"))->DefaultValue =
        TEXT("DOR_PresetRecovery_v1");
    FindPin(DoesRecoveryExist, TEXT("UserIndex"))->DefaultValue = TEXT("0");
    UK2Node_IfThenElse* ExistsBranch =
        AddNode<UK2Node_IfThenElse>(Graph, 780, 0);
    ExistsBranch->AllocateDefaultPins();
    UK2Node_CallFunction* LoadRecovery = AddCall(
        Graph,
        UGameplayStatics::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UGameplayStatics, LoadGameFromSlot),
        1040,
        -80);
    FindPin(LoadRecovery, TEXT("SlotName"))->DefaultValue =
        TEXT("DOR_PresetRecovery_v1");
    FindPin(LoadRecovery, TEXT("UserIndex"))->DefaultValue = TEXT("0");
    UK2Node_DynamicCast* CastRecovery =
        AddNode<UK2Node_DynamicCast>(Graph, 1300, -80);
    CastRecovery->TargetType = RecoveryClass;
    CastRecovery->SetPurity(false);
    CastRecovery->AllocateDefaultPins();
    ForcePinType(
        CastRecovery->GetCastSourcePin(), MakeObjectPinType(UObject::StaticClass(), false));
    UK2Node_VariableGet* GetPending = AddExternalVariableGet(
        Graph, TEXT("Pending"), RecoveryClass, 1560, 80);
    UK2Node_IfThenElse* PendingBranch =
        AddNode<UK2Node_IfThenElse>(Graph, 1820, -80);
    PendingBranch->AllocateDefaultPins();
    UK2Node_VariableGet* GetBuildTag = AddExternalVariableGet(
        Graph, TEXT("BuildTag"), RecoveryClass, 1820, 160);
    UK2Node_CallFunction* IsCurrentRecovery = AddCall(
        Graph,
        UKismetStringLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetStringLibrary, EqualEqual_StrStr),
        2080,
        80);
    FindPin(IsCurrentRecovery, TEXT("B"))->DefaultValue = DORResearchBuildTag;
    UK2Node_IfThenElse* CurrentRecoveryBranch =
        AddNode<UK2Node_IfThenElse>(Graph, 2340, 80);
    CurrentRecoveryBranch->AllocateDefaultPins();

    UK2Node_CallFunction* GetSaveGame = AddCall(
        Graph,
        UGameFunctionLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UGameFunctionLibrary, GetFSDSaveGame),
        2080,
        -80);
    UK2Node_VariableGet* GetCharacterSnapshot = AddExternalVariableGet(
        Graph, TEXT("CharacterSavesSnapshot"), RecoveryClass, 2080, 160);
    ForcePinType(GetCharacterSnapshot->GetValuePin(), CharacterSaveArrayType);
    UK2Node_VariableGet* GetLoadoutSnapshot = AddExternalVariableGet(
        Graph, TEXT("UpgradeLoadoutsSnapshot"), RecoveryClass, 2080, 320);
    ForcePinType(GetLoadoutSnapshot->GetValuePin(), UpgradeLoadoutArrayType);
    UK2Node_VariableSet* RestoreCharacters = AddExternalVariableSet(
        Graph, TEXT("CharacterSaves"), UFSDSaveGame::StaticClass(), 2340, -80);
    ForcePinType(
        FindPin(RestoreCharacters, TEXT("CharacterSaves")), CharacterSaveArrayType);
    UK2Node_VariableSet* RestoreLoadouts = AddExternalVariableSet(
        Graph,
        TEXT("ItemUpgradeLoadouts"),
        UFSDSaveGame::StaticClass(),
        2600,
        -80);
    ForcePinType(
        FindPin(RestoreLoadouts, TEXT("ItemUpgradeLoadouts")),
        UpgradeLoadoutArrayType);
    UK2Node_CallFunction* SaveRestoredPreset = AddCall(
        Graph,
        UFSDSaveGame::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UFSDSaveGame, SaveToDisk),
        2860,
        -80);
    UK2Node_CallFunction* DeleteRecovery = AddCall(
        Graph,
        UGameplayStatics::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UGameplayStatics, DeleteGameInSlot),
        3120,
        -80);
    FindPin(DeleteRecovery, TEXT("SlotName"))->DefaultValue =
        TEXT("DOR_PresetRecovery_v1");
    FindPin(DeleteRecovery, TEXT("UserIndex"))->DefaultValue = TEXT("0");
    UK2Node_CallFunction* RestoredMessage = AddCall(
        Graph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, PrintString),
        3380,
        -80);
    FindPin(RestoredMessage, TEXT("InString"))->DefaultValue =
        TEXT("[DOR-RECOVERY][R90] 检测到未完成的临时预设事务；已从独立恢复记录还原外部预设并保存。");
    FindPin(RestoredMessage, TEXT("bPrintToScreen"))->DefaultValue = TEXT("true");
    FindPin(RestoredMessage, TEXT("bPrintToLog"))->DefaultValue = TEXT("true");
    FindPin(RestoredMessage, TEXT("Duration"))->DefaultValue = TEXT("20.0");
    UK2Node_CallFunction* InvalidRecoveryMessage = AddCall(
        Graph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, PrintString),
        1560,
        -300);
    FindPin(InvalidRecoveryMessage, TEXT("InString"))->DefaultValue =
        TEXT("[DOR-RECOVERY][R91] 恢复记录存在但无法读取；已停止自动修改，请先备份并人工检查装备预设。");
    FindPin(InvalidRecoveryMessage, TEXT("bPrintToScreen"))->DefaultValue = TEXT("true");
    FindPin(InvalidRecoveryMessage, TEXT("bPrintToLog"))->DefaultValue = TEXT("true");
    FindPin(InvalidRecoveryMessage, TEXT("Duration"))->DefaultValue = TEXT("30.0");
    UK2Node_CallFunction* LegacyRecoveryMessage = AddCall(
        Graph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, PrintString),
        2600,
        160);
    FindPin(LegacyRecoveryMessage, TEXT("InString"))->DefaultValue =
        TEXT("[DOR-RECOVERY][R92] 检测到旧版本恢复记录；Alpha35遵照用户要求不自动修改存档，请自行处理该恢复槽。");
    FindPin(LegacyRecoveryMessage, TEXT("bPrintToScreen"))->DefaultValue = TEXT("true");
    FindPin(LegacyRecoveryMessage, TEXT("bPrintToLog"))->DefaultValue = TEXT("true");
    FindPin(LegacyRecoveryMessage, TEXT("Duration"))->DefaultValue = TEXT("30.0");
    UK2Node_CallFunction* ProbeInterruptedMessage = AddCall(
        Graph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, PrintString),
        2080,
        420);
    FindPin(ProbeInterruptedMessage, TEXT("InString"))->DefaultValue =
        TEXT("[DOR-RECOVERY][Q01] 上一次测试停在只读刷新探针；外部预设当时尚未修改，已删除探针记录。");
    FindPin(ProbeInterruptedMessage, TEXT("bPrintToScreen"))->DefaultValue = TEXT("true");
    FindPin(ProbeInterruptedMessage, TEXT("bPrintToLog"))->DefaultValue = TEXT("true");
    FindPin(ProbeInterruptedMessage, TEXT("Duration"))->DefaultValue = TEXT("30.0");
    UK2Node_CallFunction* DeleteProbeRecovery = AddCall(
        Graph,
        UGameplayStatics::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UGameplayStatics, DeleteGameInSlot),
        2340,
        420);
    FindPin(DeleteProbeRecovery, TEXT("SlotName"))->DefaultValue =
        TEXT("DOR_PresetRecovery_v1");
    FindPin(DeleteProbeRecovery, TEXT("UserIndex"))->DefaultValue = TEXT("0");

    bool bOk = true;
    bOk &= Connect(
        BeginPlay->FindPin(UEdGraphSchema_K2::PN_Then), Delay->GetExecPin());
    bOk &= Connect(SelfPin(Graph, 100, 180), FindPin(Delay, TEXT("WorldContextObject")));
    bOk &= Connect(Delay->GetThenPin(), DoesRecoveryExist->GetExecPin());
    bOk &= Connect(DoesRecoveryExist->GetThenPin(), ExistsBranch->GetExecPin());
    bOk &= Connect(
        DoesRecoveryExist->GetReturnValuePin(), ExistsBranch->GetConditionPin());
    bOk &= Connect(ExistsBranch->GetThenPin(), LoadRecovery->GetExecPin());
    bOk &= Connect(LoadRecovery->GetReturnValuePin(), CastRecovery->GetCastSourcePin());
    bOk &= Connect(LoadRecovery->GetThenPin(), CastRecovery->GetExecPin());
    bOk &= Connect(CastRecovery->GetValidCastPin(), PendingBranch->GetExecPin());
    bOk &= Connect(CastRecovery->GetInvalidCastPin(), InvalidRecoveryMessage->GetExecPin());
    bOk &= Connect(
        CastRecovery->GetCastResultPin(), FindPin(GetPending, UEdGraphSchema_K2::PN_Self));
    bOk &= Connect(GetPending->GetValuePin(), PendingBranch->GetConditionPin());
    bOk &= Connect(
        CastRecovery->GetCastResultPin(),
        FindPin(GetBuildTag, UEdGraphSchema_K2::PN_Self));
    bOk &= Connect(GetBuildTag->GetValuePin(), FindPin(IsCurrentRecovery, TEXT("A")));
    bOk &= Connect(
        PendingBranch->GetThenPin(), CurrentRecoveryBranch->GetExecPin());
    bOk &= Connect(
        PendingBranch->GetElsePin(), ProbeInterruptedMessage->GetExecPin());
    bOk &= Connect(
        ProbeInterruptedMessage->GetThenPin(), DeleteProbeRecovery->GetExecPin());
    bOk &= Connect(
        SelfPin(Graph, 1920, 560),
        FindPin(ProbeInterruptedMessage, TEXT("WorldContextObject")));
    bOk &= Connect(
        IsCurrentRecovery->GetReturnValuePin(),
        CurrentRecoveryBranch->GetConditionPin());
    bOk &= Connect(
        CurrentRecoveryBranch->GetThenPin(), RestoreCharacters->GetExecPin());
    bOk &= Connect(
        CurrentRecoveryBranch->GetElsePin(), LegacyRecoveryMessage->GetExecPin());
    bOk &= Connect(
        SelfPin(Graph, 1920, -260), FindPin(GetSaveGame, TEXT("WorldContextObject")));
    bOk &= Connect(
        GetSaveGame->GetReturnValuePin(),
        FindPin(RestoreCharacters, UEdGraphSchema_K2::PN_Self));
    bOk &= Connect(
        CastRecovery->GetCastResultPin(),
        FindPin(GetCharacterSnapshot, UEdGraphSchema_K2::PN_Self));
    bOk &= Connect(
        GetCharacterSnapshot->GetValuePin(),
        FindPin(RestoreCharacters, TEXT("CharacterSaves")));
    bOk &= Connect(
        FindPin(RestoreCharacters, UEdGraphSchema_K2::PN_Then),
        RestoreLoadouts->GetExecPin());
    bOk &= Connect(
        GetSaveGame->GetReturnValuePin(),
        FindPin(RestoreLoadouts, UEdGraphSchema_K2::PN_Self));
    bOk &= Connect(
        CastRecovery->GetCastResultPin(),
        FindPin(GetLoadoutSnapshot, UEdGraphSchema_K2::PN_Self));
    bOk &= Connect(
        GetLoadoutSnapshot->GetValuePin(),
        FindPin(RestoreLoadouts, TEXT("ItemUpgradeLoadouts")));
    bOk &= Connect(
        FindPin(RestoreLoadouts, UEdGraphSchema_K2::PN_Then),
        SaveRestoredPreset->GetExecPin());
    bOk &= Connect(
        GetSaveGame->GetReturnValuePin(),
        FindPin(SaveRestoredPreset, UEdGraphSchema_K2::PN_Self));
    bOk &= Connect(SaveRestoredPreset->GetThenPin(), DeleteRecovery->GetExecPin());
    bOk &= Connect(DeleteRecovery->GetThenPin(), RestoredMessage->GetExecPin());
    bOk &= Connect(
        SelfPin(Graph, 3220, 120),
        FindPin(RestoredMessage, TEXT("WorldContextObject")));
    bOk &= Connect(
        SelfPin(Graph, 1400, -120),
        FindPin(InvalidRecoveryMessage, TEXT("WorldContextObject")));

    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    return bOk && Blueprint->Status != BS_Error;
}

bool BuildDORWaveController(
    UBlueprint* Blueprint,
    UObject* WarningDialog)
{
    if (!Blueprint || !WarningDialog)
    {
        return false;
    }
    UObject* ContactDialog = LoadObject<UObject>(
        nullptr,
        TEXT("/Game/Character/Shouts/MissionControl/"
             "Shout_Mission_Wave_ContactWithEnemies."
             "Shout_Mission_Wave_ContactWithEnemies"));
    UObject* EndDialog = LoadObject<UObject>(
        nullptr,
        TEXT("/Game/Character/Shouts/MissionControl/"
             "Shout_Mission_WaveWarning_End."
             "Shout_Mission_WaveWarning_End"));
    UClass* CommunicationClass =
        LoadObject<UClass>(nullptr, TEXT("/Script/FSD.CommunicationComponent"));
    UClass* EnemyWaveControllerClass =
        LoadObject<UClass>(nullptr, TEXT("/Script/FSD.EnemyWaveController"));
    if (!ContactDialog || !EndDialog || !CommunicationClass ||
        !EnemyWaveControllerClass)
    {
        return false;
    }

    bool bOk = true;
    bOk &= AddTypedVariable(
        Blueprint,
        TEXT("DOR_SpawnLocations"),
        MakeStructPinType(TBaseStructure<FVector>::Get(), true));
    bOk &= AddVariable(
        Blueprint,
        TEXT("DOR_ConstantPressureActive"),
        UEdGraphSchema_K2::PC_Boolean);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);

    UEdGraph* Graph = FBlueprintEditorUtils::FindEventGraph(Blueprint);
    if (!bOk || !Graph)
    {
        return false;
    }
    Graph->Nodes.Empty();

    auto AddTimer = [&](UEdGraphPin* ExecIn,
                        const FName FunctionName,
                        int32 X,
                        int32 Y,
                        float Delay,
                        float RandomMin = -1.0f,
                        float RandomMax = -1.0f) -> UEdGraphPin*
    {
        UK2Node_CallFunction* Timer = AddCall(
            Graph,
            UKismetSystemLibrary::StaticClass(),
            GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, K2_SetTimer),
            X,
            Y);
        FindPin(Timer, TEXT("FunctionName"))->DefaultValue =
            FunctionName.ToString();
        FindPin(Timer, TEXT("bLooping"))->DefaultValue = TEXT("false");
        FindPin(Timer, TEXT("InitialStartDelay"))->DefaultValue = TEXT("0.0");
        bOk &= Connect(
            SelfPin(Graph, X - 100, Y + 180),
            FindPin(Timer, TEXT("Object")));
        if (RandomMin >= 0.0f && RandomMax >= RandomMin)
        {
            UK2Node_CallFunction* RandomDelay = AddCall(
                Graph,
                UKismetMathLibrary::StaticClass(),
                GET_FUNCTION_NAME_CHECKED(
                    UKismetMathLibrary,
                    RandomFloatInRange),
                X - 220,
                Y + 120);
            FindPin(RandomDelay, TEXT("Min"))->DefaultValue =
                FString::SanitizeFloat(RandomMin);
            FindPin(RandomDelay, TEXT("Max"))->DefaultValue =
                FString::SanitizeFloat(RandomMax);
            bOk &= Connect(
                RandomDelay->GetReturnValuePin(),
                FindPin(Timer, TEXT("Time")));
        }
        else
        {
            FindPin(Timer, TEXT("Time"))->DefaultValue =
                FString::SanitizeFloat(Delay);
        }
        bOk &= Connect(ExecIn, Timer->GetExecPin());
        return Timer->GetThenPin();
    };

    auto AddMissionShout = [&](UEdGraphPin* ExecIn,
                               UObject* Dialog,
                               int32 X,
                               int32 Y) -> UEdGraphPin*
    {
        UK2Node_CallFunction* Shout = AddCall(
            Graph,
            CommunicationClass,
            TEXT("MissionShout"),
            X,
            Y);
        FindPin(Shout, TEXT("NewShout"))->DefaultObject = Dialog;
        FindPin(Shout, TEXT("bPriority"))->DefaultValue = TEXT("true");
        bOk &= Connect(
            SelfPin(Graph, X - 100, Y + 180),
            FindPin(Shout, TEXT("WorldContext")));
        bOk &= Connect(ExecIn, Shout->GetExecPin());
        return Shout->GetThenPin();
    };

    auto AddSpawn = [&](UEdGraphPin* ExecIn,
                        float Budget,
                        bool bRefreshLocations,
                        bool bConstantPressure,
                        int32 X,
                        int32 Y) -> UEdGraphPin*
    {
        UEdGraphPin* CurrentExec = ExecIn;
        if (bRefreshLocations)
        {
            UK2Node_CallFunction* GetSpawnPoints = AddCall(
                Graph,
                USpawningBlueprintLibrary::StaticClass(),
                GET_FUNCTION_NAME_CHECKED(
                    USpawningBlueprintLibrary,
                    GetSpawnPointsInRange),
                X,
                Y + 180);
            FindPin(GetSpawnPoints, TEXT("distanceToPlayers"))->DefaultValue =
                TEXT("2000.0");
            FindPin(GetSpawnPoints, TEXT("spawnPointCount"))->DefaultValue =
                TEXT("3");
            FindPin(GetSpawnPoints, TEXT("pfSize"))->DefaultValue =
                TEXT("Medium");
            bOk &= Connect(
                SelfPin(Graph, X - 100, Y + 340),
                FindPin(GetSpawnPoints, TEXT("WorldContextObject")));
            UK2Node_VariableSet* SetLocations = AddVariableSet(
                Graph,
                TEXT("DOR_SpawnLocations"),
                X + 260,
                Y);
            bOk &= Connect(CurrentExec, SetLocations->GetExecPin());
            bOk &= Connect(
                GetSpawnPoints->GetReturnValuePin(),
                FindPin(SetLocations, TEXT("DOR_SpawnLocations")));
            CurrentExec =
                FindPin(SetLocations, UEdGraphSchema_K2::PN_Then);
        }

        UK2Node_VariableGet* Locations = AddVariableGet(
            Graph,
            TEXT("DOR_SpawnLocations"),
            X + 260,
            Y + 180);
        UK2Node_MakeArray* EmptyBannedEnemies =
            AddNode<UK2Node_MakeArray>(Graph, X + 520, Y + 220);
        EmptyBannedEnemies->NumInputs = 0;
        EmptyBannedEnemies->AllocateDefaultPins();
        ForcePinType(
            EmptyBannedEnemies->GetOutputPin(),
            MakeObjectPinType(UEnemyDescriptor::StaticClass(), true));
        UK2Node_CallFunction* Spawn = AddCall(
            Graph,
            USpawningBlueprintLibrary::StaticClass(),
            GET_FUNCTION_NAME_CHECKED(
                USpawningBlueprintLibrary,
                SpawnEnemiesFromPool),
            X + 520,
            Y);
        FindPin(Spawn, TEXT("Difficulty"))->DefaultValue =
            FString::SanitizeFloat(Budget);
        FindPin(Spawn, TEXT("Alert"))->DefaultValue = TEXT("true");
        FindPin(Spawn, TEXT("isConstantPreassure"))->DefaultValue =
            bConstantPressure ? TEXT("true") : TEXT("false");
        bOk &= Connect(
            SelfPin(Graph, X + 420, Y + 360),
            FindPin(Spawn, TEXT("WorldContextObject")));
        bOk &= Connect(
            Locations->GetValuePin(),
            FindPin(Spawn, TEXT("Locations")));
        bOk &= Connect(
            EmptyBannedEnemies->GetOutputPin(),
            FindPin(Spawn, TEXT("BannedEnemies")));
        bOk &= Connect(CurrentExec, Spawn->GetExecPin());
        return Spawn->GetThenPin();
    };

    UK2Node_Event* StartWave = AddNode<UK2Node_Event>(Graph, 0, 0);
    StartWave->EventReference.SetExternalMember(
        TEXT("StartWave"),
        EnemyWaveControllerClass);
    StartWave->bOverrideFunction = true;
    StartWave->AllocateDefaultPins();
    UK2Node_VariableSet* SetNotComplete = AddExternalVariableSet(
        Graph,
        TEXT("IsComplete"),
        EnemyWaveControllerClass,
        260,
        0);
    FindPin(SetNotComplete, TEXT("IsComplete"))->DefaultValue = TEXT("false");
    UK2Node_VariableSet* SetConstantInactive = AddVariableSet(
        Graph,
        TEXT("DOR_ConstantPressureActive"),
        520,
        0);
    FindPin(SetConstantInactive, TEXT("DOR_ConstantPressureActive"))
        ->DefaultValue = TEXT("false");
    bOk &= Connect(
        StartWave->FindPin(UEdGraphSchema_K2::PN_Then),
        SetNotComplete->GetExecPin());
    bOk &= Connect(
        SelfPin(Graph, 120, 180),
        FindPin(SetNotComplete, UEdGraphSchema_K2::PN_Self));
    bOk &= Connect(
        FindPin(SetNotComplete, UEdGraphSchema_K2::PN_Then),
        SetConstantInactive->GetExecPin());
    AddTimer(
        FindPin(SetConstantInactive, UEdGraphSchema_K2::PN_Then),
        TEXT("DOR_Warn"),
        780,
        0,
        3.7f);

    UK2Node_CustomEvent* Warn = AddCustomEvent(
        Graph,
        TEXT("DOR_Warn"),
        FUNC_BlueprintCallable,
        0,
        600);
    UEdGraphPin* WarnThen = AddMissionShout(
        Warn->FindPin(UEdGraphSchema_K2::PN_Then),
        WarningDialog,
        260,
        600);
    AddTimer(WarnThen, TEXT("DOR_BeginMainWave"), 520, 600, 20.0f);

    UK2Node_CustomEvent* BeginMain = AddCustomEvent(
        Graph,
        TEXT("DOR_BeginMainWave"),
        FUNC_BlueprintCallable,
        0,
        1200);
    UK2Node_CallFunction* PlayMusic = AddSelfCall(
        Graph,
        TEXT("PlayWaveMusac"),
        260,
        1200);
    bOk &= Connect(
        BeginMain->FindPin(UEdGraphSchema_K2::PN_Then),
        PlayMusic->GetExecPin());
    UEdGraphPin* ContactThen = AddMissionShout(
        PlayMusic->GetThenPin(),
        ContactDialog,
        520,
        1200);
    UEdGraphPin* FirstSpawnThen = AddSpawn(
        ContactThen,
        270.0f,
        true,
        false,
        780,
        1200);
    UK2Node_VariableSet* SetConstantActive = AddVariableSet(
        Graph,
        TEXT("DOR_ConstantPressureActive"),
        1560,
        1200);
    FindPin(SetConstantActive, TEXT("DOR_ConstantPressureActive"))
        ->DefaultValue = TEXT("true");
    bOk &= Connect(FirstSpawnThen, SetConstantActive->GetExecPin());
    UEdGraphPin* Main2Scheduled = AddTimer(
        FindPin(SetConstantActive, UEdGraphSchema_K2::PN_Then),
        TEXT("DOR_MainWave2"),
        1820,
        1120,
        0.0f,
        15.0f,
        25.0f);
    AddTimer(
        Main2Scheduled,
        TEXT("DOR_ConstantPressure"),
        2080,
        1280,
        0.0f,
        10.0f,
        15.0f);

    auto BuildMainStage = [&](const FName EventName,
                              float Budget,
                              bool bRefresh,
                              const FName NextEvent,
                              float Delay,
                              float DelayMin,
                              float DelayMax,
                              int32 Y)
    {
        UK2Node_CustomEvent* Stage = AddCustomEvent(
            Graph,
            EventName,
            FUNC_BlueprintCallable,
            0,
            Y);
        UEdGraphPin* SpawnThen = AddSpawn(
            Stage->FindPin(UEdGraphSchema_K2::PN_Then),
            Budget,
            bRefresh,
            false,
            260,
            Y);
        AddTimer(
            SpawnThen,
            NextEvent,
            1040,
            Y,
            Delay,
            DelayMin,
            DelayMax);
    };
    BuildMainStage(
        TEXT("DOR_MainWave2"),
        220.0f,
        false,
        TEXT("DOR_MainWave3"),
        0.0f,
        10.0f,
        20.0f,
        1900);
    BuildMainStage(
        TEXT("DOR_MainWave3"),
        120.0f,
        true,
        TEXT("DOR_MainWave4"),
        0.0f,
        10.0f,
        20.0f,
        2500);
    BuildMainStage(
        TEXT("DOR_MainWave4"),
        100.0f,
        false,
        TEXT("DOR_MainWave5"),
        0.0f,
        10.0f,
        20.0f,
        3100);
    BuildMainStage(
        TEXT("DOR_MainWave5"),
        90.0f,
        true,
        TEXT("DOR_EndWave"),
        5.0f,
        -1.0f,
        -1.0f,
        3700);

    UK2Node_CustomEvent* ConstantPressure = AddCustomEvent(
        Graph,
        TEXT("DOR_ConstantPressure"),
        FUNC_BlueprintCallable,
        0,
        4400);
    UK2Node_VariableGet* ConstantActive = AddVariableGet(
        Graph,
        TEXT("DOR_ConstantPressureActive"),
        260,
        4520);
    UK2Node_IfThenElse* ConstantBranch =
        AddNode<UK2Node_IfThenElse>(Graph, 520, 4400);
    ConstantBranch->AllocateDefaultPins();
    bOk &= Connect(
        ConstantPressure->FindPin(UEdGraphSchema_K2::PN_Then),
        ConstantBranch->GetExecPin());
    bOk &= Connect(
        ConstantActive->GetValuePin(),
        ConstantBranch->GetConditionPin());
    UK2Node_CallFunction* ConstantBudget = AddCall(
        Graph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(
            UKismetMathLibrary,
            RandomFloatInRange),
        780,
        4580);
    FindPin(ConstantBudget, TEXT("Min"))->DefaultValue = TEXT("20.0");
    FindPin(ConstantBudget, TEXT("Max"))->DefaultValue = TEXT("40.0");
    UEdGraphPin* ConstantSpawnThen = AddSpawn(
        ConstantBranch->GetThenPin(),
        20.0f,
        false,
        true,
        780,
        4400);
    // Override the fixed helper budget with the vanilla random 20-40 budget.
    for (UEdGraphNode* Node : Graph->Nodes)
    {
        UK2Node_CallFunction* Candidate = Cast<UK2Node_CallFunction>(Node);
        if (Candidate &&
            Candidate->NodePosX == 1300 &&
            Candidate->NodePosY == 4400 &&
            Candidate->GetFunctionName() ==
                GET_FUNCTION_NAME_CHECKED(
                    USpawningBlueprintLibrary,
                    SpawnEnemiesFromPool))
        {
            bOk &= Connect(
                ConstantBudget->GetReturnValuePin(),
                FindPin(Candidate, TEXT("Difficulty")));
            break;
        }
    }
    AddTimer(
        ConstantSpawnThen,
        TEXT("DOR_ConstantPressure"),
        1560,
        4400,
        0.0f,
        10.0f,
        15.0f);

    UK2Node_CustomEvent* EndWave = AddCustomEvent(
        Graph,
        TEXT("DOR_EndWave"),
        FUNC_BlueprintCallable,
        0,
        5100);
    UEdGraphPin* EndShoutThen = AddMissionShout(
        EndWave->FindPin(UEdGraphSchema_K2::PN_Then),
        EndDialog,
        260,
        5100);
    AddTimer(EndShoutThen, TEXT("DOR_StopWave"), 520, 5100, 30.0f);

    UK2Node_CustomEvent* StopWave = AddCustomEvent(
        Graph,
        TEXT("DOR_StopWave"),
        FUNC_BlueprintCallable,
        0,
        5700);
    UK2Node_CallFunction* StopMusic = AddSelfCall(
        Graph,
        TEXT("StopWaveMusac"),
        260,
        5700);
    bOk &= Connect(
        StopWave->FindPin(UEdGraphSchema_K2::PN_Then),
        StopMusic->GetExecPin());
    UK2Node_VariableSet* DisableConstant = AddVariableSet(
        Graph,
        TEXT("DOR_ConstantPressureActive"),
        520,
        5700);
    FindPin(DisableConstant, TEXT("DOR_ConstantPressureActive"))
        ->DefaultValue = TEXT("false");
    bOk &= Connect(
        StopMusic->GetThenPin(),
        DisableConstant->GetExecPin());
    AddTimer(
        FindPin(DisableConstant, UEdGraphSchema_K2::PN_Then),
        TEXT("DOR_CompleteWave"),
        780,
        5700,
        70.0f);

    UK2Node_CustomEvent* CompleteWave = AddCustomEvent(
        Graph,
        TEXT("DOR_CompleteWave"),
        FUNC_BlueprintCallable,
        0,
        6300);
    UK2Node_VariableSet* SetComplete = AddExternalVariableSet(
        Graph,
        TEXT("IsComplete"),
        EnemyWaveControllerClass,
        260,
        6300);
    FindPin(SetComplete, TEXT("IsComplete"))->DefaultValue = TEXT("true");
    bOk &= Connect(
        CompleteWave->FindPin(UEdGraphSchema_K2::PN_Then),
        SetComplete->GetExecPin());
    bOk &= Connect(
        SelfPin(Graph, 120, 6480),
        FindPin(SetComplete, UEdGraphSchema_K2::PN_Self));

    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    return bOk && Blueprint->Status != BS_Error;
}

bool CreateSecondaryWaveControllers(
    const TArray<UObject*>& AnnouncementAssets,
    TArray<UBlueprint*>& OutControllers)
{
    UClass* BaseClass = LoadObject<UClass>(
        nullptr,
        TEXT("/Game/Enemies/Waves/WaveControllers/"
             "EWC_Base.EWC_Base_C"));
    if (!BaseClass ||
        AnnouncementAssets.Num() != SecondaryAnnouncements().Num())
    {
        return false;
    }
    for (int32 Index = 0; Index < SecondaryAnnouncements().Num(); ++Index)
    {
        const FDORSecondaryAnnouncement& Row =
            SecondaryAnnouncements()[Index];
        const FString AssetName =
            FString::Printf(TEXT("BP_DOR_Wave_%s"), Row.AssetName);
        UBlueprint* Controller = CreateObjectBlueprint(
            FString(RuntimeRoot) / TEXT("Waves") / AssetName,
            AssetName,
            BaseClass);
        if (!Controller ||
            !BuildDORWaveController(
                Controller,
                AnnouncementAssets[Index]) ||
            !SaveBlueprint(Controller))
        {
            return false;
        }
        OutControllers.Add(Controller);
    }
    return OutControllers.Num() == SecondaryAnnouncements().Num();
}

bool BuildNamedLogFunction(UBlueprint* Blueprint, const FName FunctionName, const FString& LogMessage)
{
    UEdGraph* Graph = FBlueprintEditorUtils::CreateNewGraph(
        Blueprint,
        FunctionName,
        UEdGraph::StaticClass(),
        UEdGraphSchema_K2::StaticClass());
    FBlueprintEditorUtils::AddFunctionGraph<UClass>(Blueprint, Graph, true, nullptr);
    UEdGraphPin* EntryExec = nullptr;
    for (UEdGraphNode* Node : Graph->Nodes)
    {
        if (UK2Node_FunctionEntry* Entry = Cast<UK2Node_FunctionEntry>(Node))
        {
            EntryExec = Entry->FindPin(UEdGraphSchema_K2::PN_Then);
            break;
        }
    }
    UK2Node_CallFunction* Log = AddDORLog(Graph, LogMessage, 280, 0);
    return Connect(EntryExec, Log->GetExecPin());
}

bool BuildProxyMasterStubFunctions(UBlueprint* Blueprint)
{
    auto BuildStub = [&](const FName Name, bool bChoiceIndex)
    {
        UEdGraph* Graph = FBlueprintEditorUtils::CreateNewGraph(
            Blueprint,
            Name,
            UEdGraph::StaticClass(),
            UEdGraphSchema_K2::StaticClass());
        FBlueprintEditorUtils::AddFunctionGraph<UClass>(Blueprint, Graph, true, nullptr);
        UK2Node_FunctionEntry* Entry = FindFunctionEntry(Graph);
        if (!Entry ||
            !AddFunctionInput(
                Graph,
                TEXT("ProxyActor"),
                MakeObjectPinType(AActor::StaticClass(), false)) ||
            (bChoiceIndex && !AddFunctionInput(Graph, TEXT("ChoiceIndex"), MakeIntPinType(false))))
        {
            return false;
        }
        UK2Node_CallFunction* Log = AddDORLog(
            Graph,
            FString::Printf(TEXT("[DOR]|event=%s|result=stub"), *Name.ToString()),
            320,
            0);
        return Connect(Entry->FindPin(UEdGraphSchema_K2::PN_Then), Log->GetExecPin());
    };
    auto BuildObjectiveStub = [&](const FName Name)
    {
        UEdGraph* Graph = FBlueprintEditorUtils::CreateNewGraph(
            Blueprint,
            Name,
            UEdGraph::StaticClass(),
            UEdGraphSchema_K2::StaticClass());
        FBlueprintEditorUtils::AddFunctionGraph<UClass>(Blueprint, Graph, true, nullptr);
        UK2Node_FunctionEntry* Entry = FindFunctionEntry(Graph);
        if (!Entry ||
            !AddFunctionInput(Graph, TEXT("ObjectiveKey"), MakeStringPinType(false)))
        {
            return false;
        }
        UK2Node_CallFunction* Log = AddDORLog(
            Graph,
            FString::Printf(TEXT("[DOR]|event=%s|result=stub"), *Name.ToString()),
            320,
            0);
        return Connect(Entry->FindPin(UEdGraphSchema_K2::PN_Then), Log->GetExecPin());
    };
    auto BuildRemoteDispatchStub = [&]()
    {
        UEdGraph* Graph = FBlueprintEditorUtils::CreateNewGraph(
            Blueprint,
            TEXT("DOR_DispatchRemoteResearch"),
            UEdGraph::StaticClass(),
            UEdGraphSchema_K2::StaticClass());
        FBlueprintEditorUtils::AddFunctionGraph<UClass>(Blueprint, Graph, true, nullptr);
        UK2Node_FunctionEntry* Entry = FindFunctionEntry(Graph);
        if (!Entry ||
            !AddFunctionInput(
                Graph,
                TEXT("Player"),
                MakeObjectPinType(APlayerCharacter::StaticClass(), false)) ||
            !AddFunctionInput(Graph, TEXT("TestIndex"), MakeIntPinType(false)) ||
            !AddFunctionInput(Graph, TEXT("Action"), MakeIntPinType(false)) ||
            !AddFunctionInput(Graph, TEXT("Argument"), MakeStringPinType(false)))
        {
            return false;
        }
        UK2Node_CallFunction* Log = AddDORLog(
            Graph,
            TEXT("[DOR]|event=DOR_DispatchRemoteResearch|result=stub"),
            320,
            0);
        return Connect(Entry->FindPin(UEdGraphSchema_K2::PN_Then), Log->GetExecPin());
    };
    auto BuildReplayStub = [&](const FName Name, bool bIncludeProxy)
    {
        UEdGraph* Graph = FBlueprintEditorUtils::CreateNewGraph(
            Blueprint,
            Name,
            UEdGraph::StaticClass(),
            UEdGraphSchema_K2::StaticClass());
        FBlueprintEditorUtils::AddFunctionGraph<UClass>(Blueprint, Graph, true, nullptr);
        UK2Node_FunctionEntry* Entry = FindFunctionEntry(Graph);
        if (!Entry ||
            (bIncludeProxy &&
             !AddFunctionInput(
                 Graph,
                 TEXT("ProxyActor"),
                 MakeObjectPinType(AActor::StaticClass(), false))) ||
            !AddFunctionInput(
                Graph,
                TEXT("Player"),
                MakeObjectPinType(APlayerCharacter::StaticClass(), false)) ||
            !AddFunctionInput(Graph, TEXT("ChoiceCode"), MakeIntPinType(false)) ||
            !AddFunctionInput(Graph, TEXT("SlotName"), MakeStringPinType(false)))
        {
            return false;
        }
        UK2Node_CallFunction* Log = AddDORLog(
            Graph,
            FString::Printf(TEXT("[DOR]|event=%s|result=stub"), *Name.ToString()),
            320,
            0);
        return Connect(Entry->FindPin(UEdGraphSchema_K2::PN_Then), Log->GetExecPin());
    };
    return
        BuildStub(TEXT("DOR_StartChoiceForProxy"), false) &&
        BuildStub(TEXT("DOR_SubmitChoiceForProxy"), true) &&
        BuildObjectiveStub(TEXT("DOR_CompleteRewardRound")) &&
        BuildObjectiveStub(TEXT("DOR_TriggerAnnouncedSwarm")) &&
        BuildRemoteDispatchStub() &&
        BuildReplayStub(TEXT("DOR_PersistReplayCode"), false) &&
        BuildReplayStub(TEXT("DOR_RecordChoiceForReplay"), true) &&
        BuildNamedLogFunction(
            Blueprint,
            TEXT("DOR_ReconcilePlayerSessions"),
            TEXT("[DOR]|event=SESSION_RECONCILE|result=stub")) &&
        BuildNamedLogFunction(
            Blueprint,
            TEXT("DOR_DispatchChoiceToProxy"),
            TEXT("[DOR]|event=CHOICE_DISPATCH|result=stub")) &&
        BuildNamedLogFunction(
            Blueprint,
            TEXT("DOR_CancelActiveProxyChoice"),
            TEXT("[DOR]|event=CHOICE_CANCEL|result=stub")) &&
        BuildNamedLogFunction(
            Blueprint,
            TEXT("DOR_ReportEnemyCount"),
            TEXT("[DOR]|event=ENEMY_COUNT|result=stub"));
}

bool BuildAmmoRatioPolicyFunctions(UBlueprint* Blueprint)
{
    UClass* AmmoDrivenClass = LoadObject<UClass>(
        nullptr,
        TEXT("/Script/FSD.AmmoDrivenWeapon"));
    if (!Blueprint || !AmmoDrivenClass)
    {
        return false;
    }
    bool bOk = true;

    UEdGraph* CaptureGraph = FBlueprintEditorUtils::CreateNewGraph(
        Blueprint,
        TEXT("DOR_CaptureAmmoRatios"),
        UEdGraph::StaticClass(),
        UEdGraphSchema_K2::StaticClass());
    FBlueprintEditorUtils::AddFunctionGraph<UClass>(Blueprint, CaptureGraph, true, nullptr);
    UK2Node_FunctionEntry* CaptureEntry = FindFunctionEntry(CaptureGraph);
    UEdGraphPin* CaptureItemPin = AddFunctionInput(
        CaptureGraph,
        TEXT("Item"),
        MakeObjectPinType(AItem::StaticClass(), false));
    if (!CaptureEntry || !CaptureItemPin)
    {
        return false;
    }
    UK2Node_DynamicCast* CaptureCast = AddNode<UK2Node_DynamicCast>(
        CaptureGraph, 260, 40);
    CaptureCast->TargetType = AmmoDrivenClass;
    CaptureCast->SetPurity(true);
    CaptureCast->AllocateDefaultPins();
    ForcePinType(CaptureCast->GetCastSourcePin(), MakeObjectPinType(UObject::StaticClass()));
    UK2Node_CallFunction* CaptureValid = AddCall(
        CaptureGraph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, IsValid),
        520,
        40);
    UK2Node_IfThenElse* CaptureBranch = AddNode<UK2Node_IfThenElse>(
        CaptureGraph, 780, -140);
    CaptureBranch->AllocateDefaultPins();
    auto AddAmmoGet = [&](const FName Name, int32 Y)
    {
        return AddExternalVariableGet(
            CaptureGraph,
            Name,
            AmmoDrivenClass,
            780,
            Y);
    };
    UK2Node_VariableGet* OldAmmo = AddAmmoGet(TEXT("AmmoCount"), 120);
    UK2Node_VariableGet* OldMaxAmmo = AddAmmoGet(TEXT("MaxAmmo"), 240);
    UK2Node_VariableGet* OldClip = AddAmmoGet(TEXT("ClipCount"), 360);
    UK2Node_VariableGet* OldClipSize = AddAmmoGet(TEXT("ClipSize"), 480);
    UK2Node_CallFunction* SafeMaxAmmo = AddCall(
        CaptureGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Max),
        1040,
        240);
    FindPin(SafeMaxAmmo, TEXT("B"))->DefaultValue = TEXT("1");
    UK2Node_CallFunction* SafeClipSize = AddCall(
        CaptureGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Max),
        1040,
        480);
    FindPin(SafeClipSize, TEXT("B"))->DefaultValue = TEXT("1");
    auto AddIntToFloat = [&](int32 X, int32 Y)
    {
        return AddCall(
            CaptureGraph,
            UKismetMathLibrary::StaticClass(),
            GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Conv_IntToFloat),
            X,
            Y);
    };
    UK2Node_CallFunction* AmmoFloat = AddIntToFloat(1300, 120);
    UK2Node_CallFunction* MaxAmmoFloat = AddIntToFloat(1300, 240);
    UK2Node_CallFunction* ClipFloat = AddIntToFloat(1300, 360);
    UK2Node_CallFunction* ClipSizeFloat = AddIntToFloat(1300, 480);
    UK2Node_CallFunction* ReserveRatio = AddCall(
        CaptureGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Divide_FloatFloat),
        1560,
        180);
    UK2Node_CallFunction* ClipRatio = AddCall(
        CaptureGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Divide_FloatFloat),
        1560,
        420);
    UK2Node_VariableSet* SaveReserveRatio = AddVariableSet(
        CaptureGraph, TEXT("SavedReserveAmmoRatio"), 1820, -140);
    UK2Node_VariableSet* SaveClipRatio = AddVariableSet(
        CaptureGraph, TEXT("SavedClipAmmoRatio"), 2080, -140);
    UK2Node_CallFunction* CaptureLog = AddDORLog(
        CaptureGraph,
        TEXT("[DOR]|event=AMMO_RATIO_CAPTURE|result=ok|kind=ammo_driven"),
        2340,
        -140);
    UK2Node_VariableSet* InvalidReserve = AddVariableSet(
        CaptureGraph, TEXT("SavedReserveAmmoRatio"), 1040, -360);
    FindPin(InvalidReserve, TEXT("SavedReserveAmmoRatio"))->DefaultValue = TEXT("-1.0");
    UK2Node_VariableSet* InvalidClip = AddVariableSet(
        CaptureGraph, TEXT("SavedClipAmmoRatio"), 1300, -360);
    FindPin(InvalidClip, TEXT("SavedClipAmmoRatio"))->DefaultValue = TEXT("-1.0");
    UK2Node_CallFunction* CaptureUnsupportedLog = AddDORLog(
        CaptureGraph,
        TEXT("[DOR]|event=AMMO_RATIO_CAPTURE|result=skip|reason=non_ammo_driven"),
        1560,
        -360);

    bOk &= Connect(CaptureItemPin, CaptureCast->GetCastSourcePin());
    bOk &= Connect(CaptureCast->GetCastResultPin(), FindPin(CaptureValid, TEXT("Object")));
    bOk &= Connect(
        CaptureEntry->FindPin(UEdGraphSchema_K2::PN_Then),
        CaptureBranch->GetExecPin());
    bOk &= Connect(CaptureValid->GetReturnValuePin(), CaptureBranch->GetConditionPin());
    for (UK2Node_VariableGet* Value : {OldAmmo, OldMaxAmmo, OldClip, OldClipSize})
    {
        bOk &= Connect(
            CaptureCast->GetCastResultPin(),
            FindPin(Value, UEdGraphSchema_K2::PN_Self));
    }
    bOk &= Connect(OldMaxAmmo->GetValuePin(), FindPin(SafeMaxAmmo, TEXT("A")));
    bOk &= Connect(OldClipSize->GetValuePin(), FindPin(SafeClipSize, TEXT("A")));
    bOk &= Connect(OldAmmo->GetValuePin(), FindPin(AmmoFloat, TEXT("InInt")));
    bOk &= Connect(SafeMaxAmmo->GetReturnValuePin(), FindPin(MaxAmmoFloat, TEXT("InInt")));
    bOk &= Connect(OldClip->GetValuePin(), FindPin(ClipFloat, TEXT("InInt")));
    bOk &= Connect(SafeClipSize->GetReturnValuePin(), FindPin(ClipSizeFloat, TEXT("InInt")));
    bOk &= Connect(AmmoFloat->GetReturnValuePin(), FindPin(ReserveRatio, TEXT("A")));
    bOk &= Connect(MaxAmmoFloat->GetReturnValuePin(), FindPin(ReserveRatio, TEXT("B")));
    bOk &= Connect(ClipFloat->GetReturnValuePin(), FindPin(ClipRatio, TEXT("A")));
    bOk &= Connect(ClipSizeFloat->GetReturnValuePin(), FindPin(ClipRatio, TEXT("B")));
    bOk &= Connect(CaptureBranch->GetThenPin(), SaveReserveRatio->GetExecPin());
    bOk &= Connect(
        ReserveRatio->GetReturnValuePin(),
        FindPin(SaveReserveRatio, TEXT("SavedReserveAmmoRatio")));
    bOk &= Connect(
        FindPin(SaveReserveRatio, UEdGraphSchema_K2::PN_Then),
        SaveClipRatio->GetExecPin());
    bOk &= Connect(
        ClipRatio->GetReturnValuePin(),
        FindPin(SaveClipRatio, TEXT("SavedClipAmmoRatio")));
    bOk &= Connect(
        FindPin(SaveClipRatio, UEdGraphSchema_K2::PN_Then),
        CaptureLog->GetExecPin());
    bOk &= Connect(CaptureBranch->GetElsePin(), InvalidReserve->GetExecPin());
    bOk &= Connect(
        FindPin(InvalidReserve, UEdGraphSchema_K2::PN_Then),
        InvalidClip->GetExecPin());
    bOk &= Connect(
        FindPin(InvalidClip, UEdGraphSchema_K2::PN_Then),
        CaptureUnsupportedLog->GetExecPin());

    UEdGraph* RestoreGraph = FBlueprintEditorUtils::CreateNewGraph(
        Blueprint,
        TEXT("DOR_RestoreAmmoRatios"),
        UEdGraph::StaticClass(),
        UEdGraphSchema_K2::StaticClass());
    FBlueprintEditorUtils::AddFunctionGraph<UClass>(Blueprint, RestoreGraph, true, nullptr);
    UK2Node_FunctionEntry* RestoreEntry = FindFunctionEntry(RestoreGraph);
    UEdGraphPin* RestoreItemPin = AddFunctionInput(
        RestoreGraph,
        TEXT("Item"),
        MakeObjectPinType(AItem::StaticClass(), false));
    if (!RestoreEntry || !RestoreItemPin)
    {
        return false;
    }
    UK2Node_DynamicCast* RestoreCast = AddNode<UK2Node_DynamicCast>(
        RestoreGraph, 260, 40);
    RestoreCast->TargetType = AmmoDrivenClass;
    RestoreCast->SetPurity(true);
    RestoreCast->AllocateDefaultPins();
    ForcePinType(RestoreCast->GetCastSourcePin(), MakeObjectPinType(UObject::StaticClass()));
    UK2Node_CallFunction* RestoreValid = AddCall(
        RestoreGraph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, IsValid),
        520,
        40);
    UK2Node_VariableGet* SavedReserve = AddVariableGet(
        RestoreGraph, TEXT("SavedReserveAmmoRatio"), 520, 180);
    UK2Node_VariableGet* SavedClip = AddVariableGet(
        RestoreGraph, TEXT("SavedClipAmmoRatio"), 520, 300);
    UK2Node_CallFunction* ReserveSupported = AddCall(
        RestoreGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, GreaterEqual_FloatFloat),
        780,
        180);
    FindPin(ReserveSupported, TEXT("B"))->DefaultValue = TEXT("0.0");
    UK2Node_CallFunction* ClipSupported = AddCall(
        RestoreGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, GreaterEqual_FloatFloat),
        780,
        300);
    FindPin(ClipSupported, TEXT("B"))->DefaultValue = TEXT("0.0");
    UK2Node_CallFunction* RatiosSupported = AddCall(
        RestoreGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, BooleanAND),
        1040,
        240);
    UK2Node_CallFunction* CanRestore = AddCall(
        RestoreGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, BooleanAND),
        1300,
        160);
    UK2Node_IfThenElse* RestoreBranch = AddNode<UK2Node_IfThenElse>(
        RestoreGraph, 1560, -80);
    RestoreBranch->AllocateDefaultPins();
    UK2Node_VariableGet* NewMaxAmmo = AddExternalVariableGet(
        RestoreGraph, TEXT("MaxAmmo"), AmmoDrivenClass, 1560, 180);
    UK2Node_VariableGet* NewClipSize = AddExternalVariableGet(
        RestoreGraph, TEXT("ClipSize"), AmmoDrivenClass, 1560, 300);
    UK2Node_CallFunction* NewMaxAmmoFloat = AddCall(
        RestoreGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Conv_IntToFloat),
        1820,
        180);
    UK2Node_CallFunction* NewClipSizeFloat = AddCall(
        RestoreGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Conv_IntToFloat),
        1820,
        300);
    UK2Node_CallFunction* ScaledAmmo = AddCall(
        RestoreGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Multiply_FloatFloat),
        2080,
        180);
    UK2Node_CallFunction* ScaledClip = AddCall(
        RestoreGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Multiply_FloatFloat),
        2080,
        300);
    UK2Node_CallFunction* RoundedAmmo = AddCall(
        RestoreGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Round),
        2340,
        180);
    UK2Node_CallFunction* RoundedClip = AddCall(
        RestoreGraph,
        UKismetMathLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetMathLibrary, Round),
        2340,
        300);
    UK2Node_VariableSet* SetAmmo = AddExternalVariableSet(
        RestoreGraph, TEXT("AmmoCount"), AmmoDrivenClass, 2600, -80);
    UK2Node_VariableSet* SetClip = AddExternalVariableSet(
        RestoreGraph, TEXT("ClipCount"), AmmoDrivenClass, 2860, -80);
    UK2Node_CallFunction* RestoreLog = AddDORLog(
        RestoreGraph,
        TEXT("[DOR]|event=AMMO_RATIO_RESTORE|result=ok|kind=ammo_driven"),
        3120,
        -80);
    UK2Node_CallFunction* RestoreUnsupportedLog = AddDORLog(
        RestoreGraph,
        TEXT("[DOR]|event=AMMO_RATIO_RESTORE|result=skip|reason=non_ammo_driven"),
        1820,
        -300);

    bOk &= Connect(RestoreItemPin, RestoreCast->GetCastSourcePin());
    bOk &= Connect(RestoreCast->GetCastResultPin(), FindPin(RestoreValid, TEXT("Object")));
    bOk &= Connect(SavedReserve->GetValuePin(), FindPin(ReserveSupported, TEXT("A")));
    bOk &= Connect(SavedClip->GetValuePin(), FindPin(ClipSupported, TEXT("A")));
    bOk &= Connect(
        ReserveSupported->GetReturnValuePin(),
        FindPin(RatiosSupported, TEXT("A")));
    bOk &= Connect(
        ClipSupported->GetReturnValuePin(),
        FindPin(RatiosSupported, TEXT("B")));
    bOk &= Connect(RestoreValid->GetReturnValuePin(), FindPin(CanRestore, TEXT("A")));
    bOk &= Connect(
        RatiosSupported->GetReturnValuePin(),
        FindPin(CanRestore, TEXT("B")));
    bOk &= Connect(
        RestoreEntry->FindPin(UEdGraphSchema_K2::PN_Then),
        RestoreBranch->GetExecPin());
    bOk &= Connect(CanRestore->GetReturnValuePin(), RestoreBranch->GetConditionPin());
    for (UK2Node_VariableGet* Value : {NewMaxAmmo, NewClipSize})
    {
        bOk &= Connect(
            RestoreCast->GetCastResultPin(),
            FindPin(Value, UEdGraphSchema_K2::PN_Self));
    }
    bOk &= Connect(NewMaxAmmo->GetValuePin(), FindPin(NewMaxAmmoFloat, TEXT("InInt")));
    bOk &= Connect(NewClipSize->GetValuePin(), FindPin(NewClipSizeFloat, TEXT("InInt")));
    bOk &= Connect(SavedReserve->GetValuePin(), FindPin(ScaledAmmo, TEXT("A")));
    bOk &= Connect(NewMaxAmmoFloat->GetReturnValuePin(), FindPin(ScaledAmmo, TEXT("B")));
    bOk &= Connect(SavedClip->GetValuePin(), FindPin(ScaledClip, TEXT("A")));
    bOk &= Connect(NewClipSizeFloat->GetReturnValuePin(), FindPin(ScaledClip, TEXT("B")));
    bOk &= Connect(ScaledAmmo->GetReturnValuePin(), FindPin(RoundedAmmo, TEXT("A")));
    bOk &= Connect(ScaledClip->GetReturnValuePin(), FindPin(RoundedClip, TEXT("A")));
    bOk &= Connect(RestoreBranch->GetThenPin(), SetAmmo->GetExecPin());
    bOk &= Connect(
        RestoreCast->GetCastResultPin(),
        FindPin(SetAmmo, UEdGraphSchema_K2::PN_Self));
    bOk &= Connect(RoundedAmmo->GetReturnValuePin(), FindPin(SetAmmo, TEXT("AmmoCount")));
    bOk &= Connect(
        FindPin(SetAmmo, UEdGraphSchema_K2::PN_Then),
        SetClip->GetExecPin());
    bOk &= Connect(
        RestoreCast->GetCastResultPin(),
        FindPin(SetClip, UEdGraphSchema_K2::PN_Self));
    bOk &= Connect(RoundedClip->GetReturnValuePin(), FindPin(SetClip, TEXT("ClipCount")));
    bOk &= Connect(
        FindPin(SetClip, UEdGraphSchema_K2::PN_Then),
        RestoreLog->GetExecPin());
    bOk &= Connect(
        RestoreBranch->GetElsePin(),
        RestoreUnsupportedLog->GetExecPin());
    return bOk;
}

