bool BuildDebugNotifyFunction(UBlueprint* Blueprint)
{
    if (!Blueprint) return false;
    UEdGraph* Graph=FBlueprintEditorUtils::CreateNewGraph(Blueprint,TEXT("DOR_DebugNotify"),UEdGraph::StaticClass(),UEdGraphSchema_K2::StaticClass());
    FBlueprintEditorUtils::AddFunctionGraph<UClass>(Blueprint,Graph,true,nullptr);
    auto* Entry=FindFunctionEntry(Graph);auto* Message=AddFunctionInput(Graph,TEXT("Message"),MakeStringPinType(false));if(!Entry||!Message)return false;
    auto* Retain=AddSelfCall(Graph,TEXT("DOR_DiagnosticRetain"),260,-80);
    auto* Log=AddCall(Graph,UKismetSystemLibrary::StaticClass(),GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary,PrintString),520,-80);
    FindPin(Log,TEXT("bPrintToScreen"))->DefaultValue=TEXT("false");FindPin(Log,TEXT("bPrintToLog"))->DefaultValue=TEXT("true");FindPin(Log,TEXT("Duration"))->DefaultValue=TEXT("0.0");
    bool bOk=Connect(FindPin(Entry,UEdGraphSchema_K2::PN_Then),Retain->GetExecPin());bOk&=Connect(Message,FindPin(Retain,TEXT("Message")));bOk&=Connect(Retain->GetThenPin(),Log->GetExecPin());bOk&=Connect(SelfPin(Graph,100,-40),FindPin(Log,TEXT("WorldContextObject")));bOk&=Connect(Message,FindPin(Log,TEXT("InString")));
    auto* State=AddCall(Graph,UGameFunctionLibrary::StaticClass(),GET_FUNCTION_NAME_CHECKED(UGameFunctionLibrary,GetFSDGameState),260,80);
    auto* Post=AddCall(Graph,AFSDGameState::StaticClass(),GET_FUNCTION_NAME_CHECKED(AFSDGameState,PostGameMessage),780,-80);
    bOk&=Connect(SelfPin(Graph,100,180),FindPin(State,TEXT("WorldContextObject")));bOk&=Connect(Log->GetThenPin(),Post->GetExecPin());bOk&=Connect(State->GetReturnValuePin(),FindPin(Post,UEdGraphSchema_K2::PN_Self));bOk&=Connect(Message,FindPin(Post,TEXT("Msg")));
    return bOk;
}

