    auto AddBlockingUpgradeLoad = [&](const TCHAR* ObjectPath, int32 X, int32 Y)
    {
        UK2Node_CallFunction* MakePath = AddCall(
            Graph,
            UKismetSystemLibrary::StaticClass(),
            GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, MakeSoftObjectPath),
            X,
            Y);
        FindPin(MakePath, TEXT("PathString"))->DefaultValue = ObjectPath;
        UK2Node_CallFunction* ToSoftReference = AddCall(
            Graph,
            UKismetSystemLibrary::StaticClass(),
            GET_FUNCTION_NAME_CHECKED(
                UKismetSystemLibrary,
                Conv_SoftObjPathToSoftObjRef),
            X + 260,
            Y);
        UK2Node_CallFunction* LoadBlocking = AddCall(
            Graph,
            UKismetSystemLibrary::StaticClass(),
            GET_FUNCTION_NAME_CHECKED(
                UKismetSystemLibrary,
                LoadAsset_Blocking),
            X + 520,
            Y);
        UK2Node_DynamicCast* CastUpgrade =
            AddNode<UK2Node_DynamicCast>(Graph, X + 780, Y);
        CastUpgrade->TargetType = UItemUpgrade::StaticClass();
        CastUpgrade->SetPurity(false);
        CastUpgrade->AllocateDefaultPins();
        ForcePinType(
            CastUpgrade->GetCastSourcePin(),
            MakeObjectPinType(UObject::StaticClass(), false));
        Connect(
            MakePath->GetReturnValuePin(),
            FindPin(ToSoftReference, TEXT("SoftObjectPath")));
        Connect(
            ToSoftReference->GetReturnValuePin(),
            FindPin(LoadBlocking, TEXT("Asset")));
        Connect(
            LoadBlocking->GetReturnValuePin(),
            CastUpgrade->GetCastSourcePin());
        Connect(
            LoadBlocking->GetThenPin(),
            CastUpgrade->GetExecPin());
        return TPair<UK2Node_CallFunction*, UK2Node_DynamicCast*>(
            LoadBlocking,
            CastUpgrade);
    };

