    const FEdGraphPinType PlayerArrayType = MakeObjectPinType(APlayerCharacter::StaticClass(), true);
    const FEdGraphPinType PlayerType = MakeObjectPinType(APlayerCharacter::StaticClass(), false);
    ForEach->ResolvedWildcardType = PlayerType;
