    Branch->AllocateDefaultPins();
    UK2Node_CallFunction* AuthorityLog = AddDORLog(
        EventGraph,
        TEXT("[DOR]|event=MASTER_AUTHORITY|result=ok|role=server"),
        900,
        -80);
    UK2Node_CallFunction* ClientLog = AddDORLog(
        EventGraph,
        TEXT("[DOR]|event=MASTER_AUTHORITY|result=ok|role=client"),
        900,
        160);
    UK2Node_CallFunction* ContinuationWatchdogTimer = AddCall(
        EventGraph,
        UKismetSystemLibrary::StaticClass(),
        GET_FUNCTION_NAME_CHECKED(UKismetSystemLibrary, K2_SetTimer),
        1160,
        -80);
    FindPin(ContinuationWatchdogTimer, TEXT("FunctionName"))->DefaultValue =
        TEXT("DOR_PairContinuationTick");
    FindPin(ContinuationWatchdogTimer, TEXT("Time"))->DefaultValue = TEXT("0.5");
    FindPin(ContinuationWatchdogTimer, TEXT("bLooping"))->DefaultValue = TEXT("true");
    Connect(
        SelfPin(EventGraph, 1040, -220),
        FindPin(ContinuationWatchdogTimer, TEXT("Object")));
    bOk &= Connect(
        Log->GetThenPin(), ContinuationWatchdogTimer->GetExecPin());
    bOk &= Connect(
        ContinuationWatchdogTimer->GetThenPin(), Branch->GetExecPin());
    bOk &= Connect(IsServerWorld->GetReturnValuePin(), Branch->GetConditionPin());
    bOk &= Connect(Branch->GetThenPin(), AuthorityLog->GetExecPin());
    bOk &= Connect(Branch->GetElsePin(), ClientLog->GetExecPin());

    bOk &= BuildAddCandidatesForSlotFunction(Blueprint);
    bOk &= BuildAppendChoiceMetadataFunction(Blueprint);
    bOk &= BuildEnterSelectionStateFunction(Blueprint);
    bOk &= BuildRestoreSelectionStateFunction(Blueprint);
    bOk &= BuildProxyMasterStubFunctions(Blueprint);
    bOk &= Connect(
        BeginPlay->FindPin(UEdGraphSchema_K2::PN_Then),
        ArchivePreviousDiagnostics->GetExecPin());
    bOk &= Connect(
        ArchivePreviousDiagnostics->GetThenPin(), RecordDiagnosticStart->GetExecPin());
    bOk &= Connect(RecordDiagnosticStart->GetThenPin(), FlushDiagnosticStart->GetExecPin());
    bOk &= Connect(FlushDiagnosticStart->GetThenPin(), Log->GetExecPin());
    bOk &= BuildDebugNotifyFunction(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildShowRewardForActivePlayerStub(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildGenerateCandidatesForActivePlayerFunction(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildProcessRewardQueueFunction(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildQueueRewardPlayersFunction(Blueprint);
    bOk &= BuildHandleSecondaryCompletedFunction(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildPollObjectivesFunction(Blueprint);
    bOk &= BuildInitializeRewardsFunction(Blueprint);
    bOk &= BuildAmmoRatioPolicyFunctions(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
