    bOk &= BuildPair388MirrorActorFunction(Blueprint);
    bOk &= BuildCommitTransientPairFunction(Blueprint);
    bOk &= BuildRollbackPair388MissionSelectionFunction(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildPair388RuntimeContextFunction(Blueprint);
    bOk &= BuildPair388RecoveryStageFunction(Blueprint, RecoveryClass);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildFinalizeFusionAmmoPolicyFunction(Blueprint);
    bOk &= BuildPair388ExternalPresetRestoreFunction(Blueprint);
    bOk &= BuildPair388DeferredPresetRestoreFunctions(Blueprint);
    bOk &= BuildPair388PresetTransactionFunction(Blueprint, RecoveryClass);
    bOk &= BuildPair388SafeApplyFunctions(Blueprint, RecoveryClass);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildApplyGF01PairFunction(Blueprint);
    bOk &= AddPresetTransactionEndPlayGuard(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildApplyPairFunction(Blueprint);
    bOk &= BuildApplyOriginalFunction(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildFinalizeRewardFunction(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildApplyRewardCodeFunction(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildClientApplyMirrorEvent(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildSubmitChoiceFunction(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildTimeoutChoiceFunction(Blueprint);
    FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(Blueprint);
    FKismetEditorUtilities::CompileBlueprint(Blueprint);
    bOk &= BuildDebugSetIndexFunction(Blueprint);
