    UEdGraphPin* SpawnedCapture = FindPin(SpawnCapture, UEdGraphSchema_K2::PN_ReturnValue);
    bOk &= Connect(
        GetController->GetReturnValuePin(),
        FindPin(CameraManager, UEdGraphSchema_K2::PN_Self));
