UDORGenerateAssetsCommandlet::UDORGenerateAssetsCommandlet()
{
    IsClient = false;
    IsEditor = true;
    IsServer = false;
    LogToConsole = true;
    ShowErrorCount = true;
}

#include "DORMaintenance164.inl"
#include "DORMaintenance165.inl"
